ipfs_datasets_py/optimizers/logic_theore:
"""Cooperative, durable resource reservations for an owned daemon attempt.

Disk accounting counts apparent file bytes under the exact named roots,
including hard links once per pathname and symlink/special-file lstat sizes
without following or opening them. It is not a filesystem quota or a global
census. Outstanding reservations remain fully charged in addition to observed
bytes. Failed or abandoned entries never expire automatically. The owner must
stop/reap its isolated child group, make artifacts durable, then explicitly call
``release(artifacts_durable=True)``. Context exit alone retains the disk claim.

CPU/RAM/process admission uses the existing host resource scheduler's canonical
trainer mapping: HAMMER_LEAN, as in pipeline_stage_scheduler._default_lane and
legal_ir_hparam_scheduler.admit_work's default policy. This does not change the
host's lane reservations. Linux group RSS and disk growth are polling
observations, not kernel-enforced hard limits.
"""
from __future__ import annotations

from contextlib import contextmanager
import copy
import fcntl
import json
import math
import os
from pathlib import Path
import re
import shutil
import stat
import tempfile
import time
import uuid

from .resource_scheduler import ResourceLane, get_global_resource_scheduler

# Campaign cap increased with operator authorization on 2026-09-28. Existing
# ledgers require an explicit, lock-held limit migration; _read never upgrades
# historical ledgers or releases their retained reservations implicitly.
MAX_STORAGE_BYTES = 80_000_000_000
MAX_LEDGER_BYTES = 8 * 1024 * 1024
MAX_RESERVATIONS = 4096
MAX_CHILDREN_PER_RESERVATION = 16
MAX_EXTERNAL_CHARGES = 128
MAX_INVENTORY_ENTRIES = 1_000_000
SCHEMA = "daemon-resource-reservations-v1"
SCHEDULER_LANE = ResourceLane.HAMMER_LEAN
SCHEDULER_WORKLOAD = "canonical_trainer"
_CHARGE_KEY = re.compile(r"[A-Za-z0-9][A-Za-z0-9_.:@+-]{0,127}\Z")


class DaemonResourceError(RuntimeError):
    """Admission, accounting, or explicit release could not be verified."""


def _integer(value, name, *, minimum=1, maximum=None):
    if type(value) is not int or value < minimum or (maximum is not None and value > maximum):
        raise DaemonResourceError(f"invalid {name}")
    return value


def _external_charges(record):
    # Original v1 records predate named charges and have an empty inventory.
    charges = record.get("external_charges", {})
    if type(charges) is not dict or len(charges) > MAX_EXTERNAL_CHARGES:
        raise DaemonResourceError("invalid external charge inventory")
    for key, value in charges.items():
        if type(key) is not str or not _CHARGE_KEY.fullmatch(key):
            raise DaemonResourceError("invalid external charge key")
        _integer(value, "external charge bytes", minimum=0, maximum=MAX_STORAGE_BYTES)
    return charges


def _safe_path(value, *, directory=False, missing=False):
    path = Path(os.path.abspath(os.fspath(value)))
    for part in [*reversed(path.parents), path]:
        try:
            info = part.lstat()
        except FileNotFoundError:
            if part == path and missing:
                return path
            raise DaemonResourceError(f"missing resource path: {part}") from None
        if stat.S_ISLNK(info.st_mode):
            raise DaemonResourceError(f"symlink resource path: {part}")
        if part != path and not stat.S_ISDIR(info.st_mode):
            raise DaemonResourceError(f"non-directory resource parent: {part}")
    if directory and not stat.S_ISDIR(info.st_mode):
        raise DaemonResourceError(f"resource root is not a directory: {path}")
    if not directory and not stat.S_ISREG(info.st_mode):
        raise DaemonResourceError(f"resource file is not regular: {path}")
    return path


def _root_identity(path):
    path = _safe_path(path, directory=True)
    info = path.stat()
    return {"path": str(path), "device": info.st_dev, "inode": info.st_ino}


def _inventory_descendant(root, directory):
    """Validate a discovered directory; only a missing descendant is absent.

    Shared roots can contain another process's temporary trees. Their deletion
    is ordinary census churn, but a missing/replaced named root, symlink or
    non-directory ancestor still invalidates the observation. This helper is
    deliberately separate from strict owned-attempt path validation.
    """
    named = Path(root["path"])
    if _root_identity(named) != root:
        raise DaemonResourceError("storage root identity changed")
    try:
        components = Path(directory).relative_to(named).parts
    except ValueError as exc:
        raise DaemonResourceError("inventory descendant is outside its named root") from exc
    current = named
    for component in components:
        current = current / component
        try:
            info = current.lstat()
        except FileNotFoundError:
            return None
        if stat.S_ISLNK(info.st_mode):
            raise DaemonResourceError(f"symlink resource path: {current}")
        if not stat.S_ISDIR(info.st_mode):
            raise DaemonResourceError(f"non-directory resource parent: {current}")
    return current


def _inventory_entry_disappeared(root, path):
    """Confirm genuine absence without treating a dangling link as missing."""
    path = Path(path)
    if _inventory_descendant(root, path.parent) is None:
        return True
    try:
        path.lstat()
    except FileNotFoundError:
        return True
    return False


def _inventory(roots, *, strict=False):
    count, total, symlinks, special = 0, 0, 0, 0
    identities = [_root_identity(root) for root in roots]
    pending = [(Path(root["path"]), root) for root in identities]
    while pending:
        directory, root = pending.pop()
        directory = (_safe_path(directory, directory=True) if strict
                     else _inventory_descendant(root, directory))
        if directory is None:
            continue
        try:
            with os.scandir(directory) as entries:
                for entry in entries:
                    count += 1
                    if count > MAX_INVENTORY_ENTRIES:
                        raise DaemonResourceError("storage inventory entry bound exceeded")
                    try:
                        info = entry.stat(follow_symlinks=False)
                    except FileNotFoundError:
                        if strict or not _inventory_entry_disappeared(root, entry.path):
                            raise
                        continue
                    if stat.S_ISLNK(info.st_mode):
                        if strict:
                            raise DaemonResourceError(f"symlink in attempt inventory: {entry.path}")
                        symlinks += 1
                        total += info.st_size
                    elif stat.S_ISDIR(info.st_mode):
                        pending.append((Path(entry.path), root))
                    elif stat.S_ISREG(info.st_mode):
                        total += info.st_size
                    else:
                        if strict:
                            raise DaemonResourceError(f"nonregular attempt entry: {entry.path}")
                        special += 1
                        total += info.st_size
        except FileNotFoundError:
            if strict or _inventory_descendant(root, directory) is not None:
                raise
    if [_root_identity(Path(root["path"])) for root in identities] != identities:
        raise DaemonResourceError("storage root identity changed")
    return {"apparent_bytes": total, "entry_count": count,
            "symlink_count": symlinks, "special_file_count": special}


def _process(pid):
    """Linux PID identity and group; no command lines or environment retained."""
    try:
        raw = (Path("/proc") / str(pid) / "stat").read_text()
    except (FileNotFoundError, ProcessLookupError):
        return None
    fields = raw[raw.rfind(")") + 2:].split()
    if len(fields) < 22:
        raise DaemonResourceError("invalid /proc process identity")
    return {"pid": pid, "state": fields[0], "parent_pid": int(fields[1]),
            "group_pid": int(fields[2]), "birth": fields[19],
            "rss_bytes": int(fields[21]) * os.sysconf("SC_PAGE_SIZE")}


def _group_usage(child):
    if child is None:
        return {"available": True, "live_processes": 0, "rss_bytes": 0}
    if not Path("/proc/self/stat").is_file():
        raise DaemonResourceError("Linux /proc is required for child group accounting")
    leader = _process(child["pid"])
    if leader is not None and leader["birth"] != child["birth"]:
        raise DaemonResourceError("child PID was reused")
    live, rss = 0, 0
    entries = list(Path("/proc").iterdir())
    if len(entries) > 100_000:
        raise DaemonResourceError("process inventory bound exceeded")
    for entry in entries:
        if entry.name.isdecimal():
            process = _process(int(entry.name))
            if process is not None and process["group_pid"] == child["pid"] and process["state"] != "Z":
                live += 1
                rss += process["rss_bytes"]
    return {"available": True, "live_processes": live, "rss_bytes": rss}


def _json_pairs(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise DaemonResourceError("duplicate disk ledger field")
        result[key] = value
    return result


class DaemonResourceReservation:
    """One explicit owner reservation; enter once, release only after durability.

    No scheduler/model/runtime injection is exposed in this production API.
    ``check_usage`` must attach the child PID immediately after Popen with
    ``start_new_session=True``; the child must be a direct child of this owner.
    The owner is responsible for stopping it on a limit error.
    """

    def __init__(self, ledger_path, *, roots, storage_bytes, memory_mb, cpu_slots=1, child_process_slots=1,
                 timeout_seconds=0, ledger_lock_timeout_seconds=None):
        self.storage_bytes = _integer(storage_bytes, "storage_bytes", maximum=MAX_STORAGE_BYTES)
        self.memory_mb = _integer(memory_mb, "memory_mb")
        self.cpu_slots = _integer(cpu_slots, "cpu_slots")
        self.child_process_slots = _integer(child_process_slots, "child_process_slots")
        if type(timeout_seconds) not in (int, float) or not math.isfinite(timeout_seconds) or timeout_seconds < 0:
            raise DaemonResourceError("invalid timeout_seconds")
        self.timeout_seconds = float(timeout_seconds)
        if ledger_lock_timeout_seconds is not None and (
                type(ledger_lock_timeout_seconds) not in (int, float)
                or not math.isfinite(ledger_lock_timeout_seconds)
                or not 0 <= ledger_lock_timeout_seconds <= 60):
            raise DaemonResourceError("invalid ledger_lock_timeout_seconds")
        # Disk bookkeeping serializes short updates even when host capacity
        # admission is fail-fast. Existing callers retain their old deadline.
        self.ledger_lock_timeout_seconds = (
            self.timeout_seconds if ledger_lock_timeout_seconds is None
            else float(ledger_lock_timeout_seconds))
        values = list(roots)
        if not 1 <= len(values) <= 64:
            raise DaemonResourceError("one to 64 storage roots required")
        self.roots = tuple(_safe_path(value, directory=True) for value in values)
        for index, root in enumerate(self.roots):
            if any(root == other or root in other.parents or other in root.parents
                   for other in self.roots[:index]):
                raise DaemonResourceError("storage roots overlap")
        self.root_identities = [_root_identity(root) for root in self.roots]
        self.ledger_path = _safe_path(ledger_path, missing=True)
        self.lock_path = self.ledger_path.with_name(self.ledger_path.name + ".lock")
        _safe_path(self.lock_path, missing=True)
        self.reservation_id = uuid.uuid4().hex
        self._owner_pid = os.getpid()
        self._lease = None
        self._record = None
        self._attempt = None
        self._child = None
        self._child_history = []
        self._entered = False
        self._cleanup_error = None

    def _verify_owner_roots(self):
        if os.getpid() != self._owner_pid:
            raise DaemonResourceError("reservation cannot move to another owner process")
        if [_root_identity(root) for root in self.roots] != self.root_identities:
            raise DaemonResourceError("storage root identity changed")

    @contextmanager
    def _locked(self):
        self._verify_owner_roots()
        _safe_path(self.lock_path, missing=True)
        descriptor = os.open(self.lock_path, os.O_CREAT | os.O_RDWR | os.O_NOFOLLOW | os.O_NONBLOCK, 0o600)
        try:
            info = os.fstat(descriptor)
            if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
                raise DaemonResourceError("lock must be an unaliased regular file")
            deadline = time.monotonic() + self.ledger_lock_timeout_seconds
            while True:
                try:
                    fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
                    break
                except BlockingIOError:
                    if time.monotonic() >= deadline:
                        raise DaemonResourceError("disk ledger lock unavailable") from None
                    time.sleep(min(0.05, max(0, deadline - time.monotonic())))
            current = self.lock_path.lstat()
            if (current.st_dev, current.st_ino) != (info.st_dev, info.st_ino):
                raise DaemonResourceError("disk ledger lock identity changed")
            self._verify_owner_roots()
            yield
        finally:
            os.close(descriptor)

    def _read(self):
        _safe_path(self.ledger_path, missing=True)
        try:
            descriptor = os.open(self.ledger_path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        except FileNotFoundError:
            if self._entered:
                raise DaemonResourceError("disk ledger disappeared") from None
            return {"schema": SCHEMA, "roots": self.root_identities,
                    "limit_bytes": MAX_STORAGE_BYTES, "reservations": {}}
        with os.fdopen(descriptor, "rb") as stream:
            info = os.fstat(stream.fileno())
            if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_size > MAX_LEDGER_BYTES:
                raise DaemonResourceError("invalid disk ledger file")
            raw = stream.read(MAX_LEDGER_BYTES + 1)
        try:
            value = json.loads(raw, object_pairs_hook=_json_pairs,
                               parse_constant=lambda _: (_ for _ in ()).throw(DaemonResourceError("nonfinite disk ledger value")))
        except (ValueError, UnicodeError) as exc:
            raise DaemonResourceError("invalid disk ledger JSON") from exc
        if type(value) is not dict or set(value) != {"schema", "roots", "limit_bytes", "reservations"}:
            raise DaemonResourceError("invalid disk ledger schema")
        if value["schema"] != SCHEMA or value["roots"] != self.root_identities or value["limit_bytes"] != MAX_STORAGE_BYTES:
            raise DaemonResourceError("disk ledger storage scope differs")
        records = value["reservations"]
        if type(records) is not dict or len(records) > MAX_RESERVATIONS:
            raise DaemonResourceError("invalid disk reservation inventory")
        for key, record in records.items():
            if type(record) is not dict or record.get("reservation_id") != key or record.get("status") not in {"reserved", "active", "retained", "released"}:
                raise DaemonResourceError("invalid disk reservation record")
            _integer(record.get("storage_bytes"), "ledger storage_bytes", maximum=MAX_STORAGE_BYTES)
            _integer(record.get("owner_pid"), "ledger owner_pid")
            if "child_process_slots" in record:
                _integer(record["child_process_slots"], "ledger child_process_slots")
            _external_charges(record)
        return value

    def _write(self, value):
        self._verify_owner_roots()
        _safe_path(self.ledger_path, missing=True)
        raw = (json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False) + "\n").encode()
        if len(raw) > MAX_LEDGER_BYTES:
            raise DaemonResourceError("disk ledger byte bound exceeded")
        temporary = None
        try:
            with tempfile.NamedTemporaryFile(dir=self.ledger_path.parent, prefix=".daemon-reservation-", delete=False) as stream:
                temporary = Path(stream.name)
                stream.write(raw)
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(temporary, self.ledger_path)
            temporary = None
            descriptor = os.open(self.ledger_path.parent, os.O_RDONLY | os.O_DIRECTORY)
            try:
                os.fsync(descriptor)
            finally:
                os.close(descriptor)
        finally:
            if temporary is not None:
                temporary.unlink(missing_ok=True)

    def _account(self, ledger, *, additional=0):
        inventory = _inventory(self.roots)
        observed = inventory["apparent_bytes"]
        outstanding = sum(row["storage_bytes"] for row in ledger["reservations"].values()
                          if row["status"] != "released")
        charged = observed + outstanding + additional
        free = min(shutil.disk_usage(root).free for root in self.roots)
        result = {"observed_apparent_bytes": observed, "outstanding_full_reservations_bytes": outstanding,
                  "additional_requested_bytes": additional, "charged_bytes": charged,
                  "limit_bytes": MAX_STORAGE_BYTES, "minimum_filesystem_free_bytes": free,
                  "scope": "named_roots_only_apparent_bytes", "inventory": inventory}
        if charged > MAX_STORAGE_BYTES or free < outstanding + additional:
            raise DaemonResourceError("storage reservation capacity exceeded")
        self._verify_owner_roots()
        return result

    def __enter__(self):
        if self._entered:
            raise DaemonResourceError("reservation can only be entered once")
        with self._locked():
            ledger = self._read()
            if len(ledger["reservations"]) >= MAX_RESERVATIONS:
                raise DaemonResourceError("disk reservation inventory full")
            observation = self._account(ledger, additional=self.storage_bytes)
            record = {"reservation_id": self.reservation_id, "status": "reserved",
                      "owner_pid": self._owner_pid, "storage_bytes": self.storage_bytes,
                      "memory_mb": self.memory_mb, "cpu_slots": self.cpu_slots,
                      "child_process_slots": self.child_process_slots,
                      "scheduler_lane": SCHEDULER_LANE.value, "workload": SCHEDULER_WORKLOAD,
                      "created_at": time.time(), "attempt_directory": None, "child": None,
                      "prior_children": [], "external_charges": {},
                      "last_usage": observation, "artifacts_durable_asserted": False}
            ledger["reservations"][self.reservation_id] = record
            self._write(ledger)
            self._record = copy.deepcopy(record)
            self._entered = True
        try:
            self._lease = get_global_resource_scheduler().acquire(
                SCHEDULER_LANE, cpu_slots=self.cpu_slots, memory_mb=self.memory_mb,
                child_process_slots=self.child_process_slots, requires_gpu=False, timeout=self.timeout_seconds,
                request_id="daemon:" + self.reservation_id)
            self._update(status="active")
        except BaseException:
            try:
                self._retain("scheduler_admission_failed")
                if self._lease is not None:
                    self._lease.release()
            except BaseException as cleanup:
                self._cleanup_error = type(cleanup).__name__
            raise
        return self

    def _update(self, **fields):
        with self._locked():
            ledger = self._read()
            record = ledger["reservations"].get(self.reservation_id)
            if record is None or record["owner_pid"] != self._owner_pid or record["storage_bytes"] != self.storage_bytes:
                raise DaemonResourceError("owned disk reservation differs")
            record.update(fields)
            self._write(ledger)
            self._record = copy.deepcopy(record)

    def _retain(self, reason):
        if self._record is not None and self._record["status"] != "released":
            self._update(status="retained", retention_reason=reason)

    def account_external_bytes(self, key: str, byte_count: int):
        """Durably charge CAS/journal bytes before the owner writes them.

        Identical keys/amounts are idempotent; changed amounts are forbidden.
        These are conservative per-attempt charges, not additional physical
        bytes in the global inventory. Failed admission does not add a charge.
        The caller must only charge outputs within this ledger's named roots.
        """
        if not self._entered or self._record["status"] == "released":
            raise DaemonResourceError("reservation is not outstanding")
        if type(key) is not str or not _CHARGE_KEY.fullmatch(key):
            raise DaemonResourceError("invalid external charge key")
        _integer(byte_count, "external charge bytes", minimum=0, maximum=MAX_STORAGE_BYTES)
        with self._locked():
            ledger = self._read()
            row = ledger["reservations"].get(self.reservation_id)
            if row is None or row["owner_pid"] != self._owner_pid or row["status"] == "released":
                raise DaemonResourceError("owned disk reservation differs")
            charges = dict(_external_charges(row))
            already_charged = key in charges
            if already_charged and charges[key] != byte_count:
                raise DaemonResourceError("external charge amount changed")
            if not already_charged and len(charges) >= MAX_EXTERNAL_CHARGES:
                raise DaemonResourceError("external charge inventory bound exceeded")
            charges[key] = byte_count
            attempt_bytes = 0
            if self._attempt is not None:
                attempt = Path(self._attempt["path"])
                if _root_identity(attempt) != self._attempt:
                    raise DaemonResourceError("attempt directory identity changed")
                attempt_bytes = _inventory([attempt], strict=True)["apparent_bytes"]
            external_bytes = sum(charges.values())
            if attempt_bytes + external_bytes > self.storage_bytes:
                raise DaemonResourceError("combined attempt and external storage byte limit exceeded")
            usage = self._account(ledger)
            usage.update(attempt_bytes=attempt_bytes, external_charged_bytes=external_bytes,
                         total_attempt_charged_bytes=attempt_bytes + external_bytes,
                         attempt_limit_bytes=self.storage_bytes, checked_at=time.time())
            row.update(external_charges=charges, last_charge_usage=usage)
            self._write(ledger)
            self._record = copy.deepcopy(row)
        return {"key": key, "bytes": byte_count, "already_charged": already_charged,
                "usage": copy.deepcopy(usage)}

    def check_usage(self, attempt_directory: Path, child_pid: int | None = None):
        if not self._entered or self._record["status"] == "released":
            raise DaemonResourceError("reservation is not outstanding")
        attempt = _safe_path(attempt_directory, directory=True)
        if not any(attempt == root or root in attempt.parents for root in self.roots):
            raise DaemonResourceError("attempt directory is outside named storage roots")
        identity = _root_identity(attempt)
        if self._attempt is not None and self._attempt != identity:
            raise DaemonResourceError("attempt directory identity changed")
        self._attempt = identity
        if child_pid is not None:
            _integer(child_pid, "child_pid")
            if self._child is None or child_pid != self._child["pid"]:
                if self._child is not None:
                    if _group_usage(self._child)["live_processes"]:
                        raise DaemonResourceError("previous child process group is still alive")
                    if len(self._child_history) >= MAX_CHILDREN_PER_RESERVATION - 1:
                        raise DaemonResourceError("reservation child history bound exceeded")
                child = _process(child_pid)
                if child is None or child["parent_pid"] != self._owner_pid or child["group_pid"] != child_pid:
                    raise DaemonResourceError("child must be an owned isolated process-group leader")
                if self._child is not None:
                    self._child_history.append({**self._child, "group_observed_dead_at": time.time()})
                self._child = {key: child[key] for key in ("pid", "birth")}
        self._update(attempt_directory=self._attempt, child=self._child,
                     prior_children=copy.deepcopy(self._child_history))
        group = _group_usage(self._child)
        attempt_bytes = _inventory([attempt], strict=True)["apparent_bytes"]
        with self._locked():
            ledger = self._read()
            usage = self._account(ledger)
            row = ledger["reservations"][self.reservation_id]
            external_bytes = sum(_external_charges(row).values())
            usage.update(attempt_bytes=attempt_bytes, attempt_limit_bytes=self.storage_bytes,
                         external_charged_bytes=external_bytes,
                         total_attempt_charged_bytes=attempt_bytes + external_bytes,
                         group_rss=group, memory_limit_bytes=self.memory_mb * 1024 * 1024,
                         reserved_child_process_slots=self.child_process_slots,
                         process_slot_estimate_exceeded=group["live_processes"] > self.child_process_slots,
                         checked_at=time.time())
            row["last_usage"] = usage
            self._write(ledger)
            self._record = copy.deepcopy(row)
        if attempt_bytes + external_bytes > self.storage_bytes:
            raise DaemonResourceError("attempt storage byte limit exceeded")
        if group["rss_bytes"] > self.memory_mb * 1024 * 1024:
            raise DaemonResourceError("child group RSS limit exceeded")
        return copy.deepcopy(usage)

    def finalize(self, attempt_directory: Path, *, artifacts_durable=False):
        """Check and release a bound, stopped attempt using one fresh census.

        This is the strict success path equivalent to a final ``check_usage``
        followed by ``release``. The full claim remains charged while limits
        are checked. Only the claim arithmetic is adjusted after success; no
        filesystem observation is cached across calls or ledger-lock scopes.
        Legacy ``release`` remains available for explicitly audited recovery.
        """
        if not self._entered:
            raise DaemonResourceError("reservation was not entered")
        if self._record["status"] == "released":
            return self.to_dict()
        if artifacts_durable is not True:
            raise DaemonResourceError("explicit artifact durability assertion required")
        attempt = _safe_path(attempt_directory, directory=True)
        if not any(attempt == root or root in attempt.parents for root in self.roots):
            raise DaemonResourceError("attempt directory is outside named storage roots")
        if self._attempt is None:
            raise DaemonResourceError("finalization requires a previously bound attempt")
        if _root_identity(attempt) != self._attempt:
            raise DaemonResourceError("attempt directory identity changed")
        started = time.monotonic()
        with self._locked():
            lock_acquired = time.monotonic()
            ledger = self._read()
            row = ledger["reservations"].get(self.reservation_id)
            if (row is None or row["owner_pid"] != self._owner_pid
                    or row["storage_bytes"] != self.storage_bytes
                    or row["status"] == "released"):
                raise DaemonResourceError("owned disk reservation differs")
            if row.get("attempt_directory") != self._attempt or row.get("child") != self._child:
                raise DaemonResourceError("bound attempt or child identity changed")
            group_started = time.monotonic()
            group = _group_usage(self._child)
            group_seconds = time.monotonic() - group_started
            attempt_started = time.monotonic()
            attempt_bytes = _inventory([attempt], strict=True)["apparent_bytes"]
            attempt_seconds = time.monotonic() - attempt_started
            account_started = time.monotonic()
            accounting = self._account(ledger)
            account_seconds = time.monotonic() - account_started
            if _root_identity(attempt) != self._attempt:
                raise DaemonResourceError("attempt directory identity changed")
            external_bytes = sum(_external_charges(row).values())
            usage = copy.deepcopy(accounting)
            usage.update(attempt_bytes=attempt_bytes, attempt_limit_bytes=self.storage_bytes,
                         external_charged_bytes=external_bytes,
                         total_attempt_charged_bytes=attempt_bytes + external_bytes,
                         group_rss=group, memory_limit_bytes=self.memory_mb * 1024 * 1024,
                         reserved_child_process_slots=self.child_process_slots,
                         process_slot_estimate_exceeded=group["live_processes"] > self.child_process_slots,
                         checked_at=time.time())
            row["last_usage"] = usage
            failure = None
            if attempt_bytes + external_bytes > self.storage_bytes:
                failure = "attempt storage byte limit exceeded"
            elif group["rss_bytes"] > self.memory_mb * 1024 * 1024:
                failure = "child group RSS limit exceeded"
            else:
                group_started = time.monotonic()
                final_group = _group_usage(self._child)
                group_seconds += time.monotonic() - group_started
                if final_group["live_processes"]:
                    failure = "child process group is still alive"
            if failure is not None:
                # Preserve the observed failed usage before context cleanup
                # retains this claim. No release event is written on failure.
                self._write(ledger)
                self._record = copy.deepcopy(row)
                raise DaemonResourceError(failure)
            final_accounting = copy.deepcopy(accounting)
            final_accounting["outstanding_full_reservations_bytes"] -= self.storage_bytes
            final_accounting["charged_bytes"] -= self.storage_bytes
            row.update(status="released", artifacts_durable_asserted=True, released_at=time.time(),
                       final_accounting=final_accounting, final_attempt_bytes=attempt_bytes,
                       final_external_charged_bytes=external_bytes,
                       final_total_charged_bytes=attempt_bytes + external_bytes,
                       attempt_exceeded_reservation=False,
                       finalization_profile={
                           "schema_version": "daemon-resource-finalization-profile/v1",
                           "ledger_lock_wait_seconds": lock_acquired - started,
                           "strict_attempt_inventory_seconds": attempt_seconds,
                           "global_accounting_seconds": account_seconds,
                           "process_check_seconds": group_seconds,
                           "global_inventory_count": 1, "strict_attempt_inventory_count": 1,
                           "scope": "one_fresh_locked_census_with_full_claim_checked_before_release",
                       })
            self._write(ledger)
            self._record = copy.deepcopy(row)
        if self._lease is not None:
            self._lease.release()
        return self.to_dict()

    def release(self, *, artifacts_durable=False):
        if not self._entered:
            raise DaemonResourceError("reservation was not entered")
        if self._record["status"] == "released":
            return self.to_dict()
        if artifacts_durable is not True:
            raise DaemonResourceError("explicit artifact durability assertion required")
        if _group_usage(self._child)["live_processes"]:
            raise DaemonResourceError("child process group is still alive")
        if self._attempt is not None and _root_identity(Path(self._attempt["path"])) != self._attempt:
            raise DaemonResourceError("attempt directory identity changed")
        with self._locked():
            ledger = self._read()
            # Completed outputs replace this reservation with observed bytes.
            row = ledger["reservations"][self.reservation_id]
            row.update(status="released", artifacts_durable_asserted=True, released_at=time.time())
            row["final_accounting"] = self._account(ledger)
            row["final_attempt_bytes"] = (_inventory([Path(self._attempt["path"])], strict=True)["apparent_bytes"]
                                          if self._attempt is not None else None)
            row["final_external_charged_bytes"] = sum(_external_charges(row).values())
            row["final_total_charged_bytes"] = (row["final_attempt_bytes"] or 0) + row["final_external_charged_bytes"]
            row["attempt_exceeded_reservation"] = row["final_total_charged_bytes"] > self.storage_bytes
            self._write(ledger)
            self._record = copy.deepcopy(row)
        if self._lease is not None:
            self._lease.release()
        return self.to_dict()

    close = release

    def to_dict(self):
        return {"schema": SCHEMA, "reservation_id": self.reservation_id,
                "scheduler_lane": SCHEDULER_LANE.value, "workload": SCHEDULER_WORKLOAD,
                "status": self._record["status"] if self._record is not None else "not_entered",
                "ledger_path": str(self.ledger_path), "roots": copy.deepcopy(self.root_identities),
                "storage_limit_bytes": MAX_STORAGE_BYTES, "record": copy.deepcopy(self._record),
                "resource_lease": self._lease.to_dict() if self._lease is not None else None,
                "cleanup_error": self._cleanup_error,
                "enforcement": "cooperative_admission_and_polled_usage_not_kernel_quota"}

    def __exit__(self, exc_type, exc, traceback):
        if self._record is not None and self._record["status"] != "released":
            try:
                try:
                    self._retain("context_failed" if exc_type else "explicit_release_required")
                finally:
                    if self._lease is not None and not _group_usage(self._child)["live_processes"]:
                        self._lease.release()
            except BaseException as cleanup:
                self._cleanup_error = type(cleanup).__name__
                if exc_type is None:
                    raise
        return False


__all__ = ["DaemonResourceReservation", "DaemonResourceError", "MAX_STORAGE_BYTES"]

"""Read-only dispatch estimates; resource leases remain the admission authority.

Logical lanes and immutable optimizer settings are deliberately absent. This
planner limits concurrent independent passes, never epochs, context, or backend.
Callers inside a reserved envelope must omit scheduler-available limits: that
envelope has already been charged to the host scheduler.
"""
from __future__ import annotations

import math
import json
import os
from pathlib import Path
from typing import Mapping

MIB = 1024 * 1024


def _integer(value, name, minimum=0):
    if type(value) is not int or value < minimum:
        raise ValueError("invalid " + name)
    return value


def _read(path):
    try:
        return Path(path).read_text().strip()
    except (OSError, UnicodeError):
        return None


def _unescape_mount(value):
    for encoded, decoded in ((r"\040", " "), (r"\011", "\t"), (r"\012", "\n"), (r"\134", "\\")):
        value = value.replace(encoded, decoded)
    return value


def _cgroup_paths(proc_root, *, mount_prefix=None):
    """Find this process's v1/v2 groups and their visible ancestors."""
    groups, result = {}, []
    for line in (_read(Path(proc_root) / "self/cgroup") or "").splitlines():
        fields = line.split(":", 2)
        if len(fields) == 3:
            groups[fields[1]] = fields[2]
    for line in (_read(Path(proc_root) / "self/mountinfo") or "").splitlines():
        left, separator, right = line.partition(" - ")
        before, after = left.split(), right.split()
        if not separator or len(before) < 5 or len(after) < 3 or after[0] not in {"cgroup", "cgroup2"}:
            continue
        controllers = set(after[2].split(","))
        for key, group in groups.items():
            if (after[0] == "cgroup2" and key) or (after[0] == "cgroup" and not controllers.intersection(key.split(","))):
                continue
            root = Path(_unescape_mount(before[3]))
            mount = Path(_unescape_mount(before[4]))
            # In a cgroup namespace, '/' is relative to the mounted group.
            try:
                relative = Path(group).relative_to(root)
            except ValueError:
                if group != "/":
                    continue
                relative = Path(".")
            if mount_prefix is not None:
                mount = Path(mount_prefix) / str(mount).lstrip("/")
            current = mount / relative
            while True:
                result.append((after[0], key, current))
                if current == mount:
                    break
                current = current.parent
    return result


def hardware_probe(*, proc_root="/proc", mount_prefix=None):
    """Observe affinity, inherited cgroup limits and currently available RAM.

    Missing host memory telemetry fails closed in ``capacity_plan``. Unlimited
    or absent cgroup limits are ``None``; malformed visible limits are errors
    and prevent dispatch. CPU load is reported, not treated as a hard quota.
    """
    errors = []
    available = None
    for line in (_read(Path(proc_root) / "meminfo") or "").splitlines():
        if line.startswith("MemAvailable:"):
            try:
                available = int(line.split()[1]) // 1024
            except (ValueError, IndexError):
                errors.append("invalid_mem_available")
    try:
        affinity = len(os.sched_getaffinity(0))
    except (AttributeError, OSError):
        affinity = None
    try:
        load = os.getloadavg()[0]
    except (AttributeError, OSError):
        load = None
    cpu_limits, memory_limits = [], []
    for version, controllers, path in _cgroup_paths(proc_root, mount_prefix=mount_prefix):
        if version == "cgroup2":
            raw = _read(path / "cpu.max")
            if raw is not None:
                try:
                    quota, period = raw.split()
                    if quota != "max":
                        if int(quota) <= 0 or int(period) <= 0:
                            raise ValueError
                        cpu_limits.append(int(quota) / int(period))
                except (ValueError, ZeroDivisionError):
                    errors.append("invalid_cgroup_cpu_limit")
            limit, used = _read(path / "memory.max"), _read(path / "memory.current")
        else:
            if "cpu" in controllers.split(","):
                quota, period = _read(path / "cpu.cfs_quota_us"), _read(path / "cpu.cfs_period_us")
                if quota is not None:
                    try:
                        if int(quota) != -1:
                            if int(quota) <= 0 or int(period) <= 0:
                                raise ValueError
                            cpu_limits.append(int(quota) / int(period))
                    except (ValueError, TypeError, ZeroDivisionError):
                        errors.append("invalid_cgroup_cpu_limit")
            if "memory" not in controllers.split(","):
                continue
            limit, used = _read(path / "memory.limit_in_bytes"), _read(path / "memory.usage_in_bytes")
        if limit not in (None, "max"):
            try:
                limit_int, used_int = int(limit), int(used)
                if limit_int < 0 or used_int < 0:
                    raise ValueError
                memory_limits.append(max(0, limit_int - used_int) // MIB)
            except (ValueError, TypeError):
                errors.append("invalid_cgroup_memory_limit")
    return {"hardware_cpu_count": os.cpu_count(), "affinity_cpu_count": affinity,
            "cgroup_cpu_count": min(cpu_limits) if cpu_limits else None,
            "available_memory_mb": available,
            "cgroup_memory_remaining_mb": min(memory_limits) if memory_limits else None,
            "load_average": load, "probe_errors": sorted(set(errors))}


def scheduler_capacity(snapshot: Mapping, lane="hammer_lean"):
    """Return unreserved root capacity, preserving other lanes' reservations.

    This consumes an existing snapshot; it neither opens nor recovers scheduler
    state. It is advisory and cannot replace atomic scheduler acquisition.
    """
    lane = getattr(lane, "value", lane)
    available = snapshot["available"]
    cpu = _integer(available["cpu_slots"], "scheduler CPU")
    memory = _integer(available["memory_mb"], "scheduler memory")
    for name, item in snapshot["lanes"].items():
        if name == lane:
            continue
        for resource in ("cpu_slots", "memory_mb"):
            protected = max(0, _integer(item["reservation"].get(resource, 0), resource)
                            - _integer(item["allocated"].get(resource, 0), resource))
            if resource == "cpu_slots":
                cpu -= protected
            else:
                memory -= protected
    return {"cpu_slots": max(0, cpu), "memory_mb": max(0, memory),
            "child_process_slots": _integer(available["child_process_slots"], "scheduler child slots")}


def scheduler_snapshot(config=None):
    """Observe the host scheduler without creating files or recovering leases.

    Atomic state replacement permits a consistent single-file read. Stale root
    leases remain charged, making this conservative until the actual scheduler
    performs recovery. A changed/corrupt configuration fails closed.
    """
    from .resource_scheduler import ResourceSchedulerConfig, RESOURCE_SCHEDULER_SCHEMA_VERSION
    config = ResourceSchedulerConfig() if config is None else config
    config.validate()
    path, expected = Path(config.state_path), config.persisted_dict()
    try:
        with path.open("rb") as handle:
            raw = handle.read(8 * 1024 * 1024 + 1)
    except FileNotFoundError:
        state = {"leases": {}, "config": expected}
    else:
        if not raw or len(raw) > 8 * 1024 * 1024:
            raise ValueError("invalid scheduler state size")
        state = json.loads(raw)
        if state.get("schema_version") != RESOURCE_SCHEDULER_SCHEMA_VERSION:
            raise ValueError("unsupported scheduler state schema")
        stored = dict(state.get("config") or {})
        stored.setdefault("total_unified_memory_mb", None)
        stored.setdefault("total_child_process_slots", 64)
        if stored != expected:
            raise ValueError("scheduler configuration changed")
    lanes = {name: {"reservation": reservation.to_dict(),
                    "allocated": {"cpu_slots": 0, "memory_mb": 0, "child_process_slots": 0}}
             for name, reservation in config.reservations().items()}
    used = {"cpu_slots": 0, "memory_mb": 0, "child_process_slots": 0}
    leases = state.get("leases")
    if type(leases) is not dict:
        raise ValueError("invalid scheduler leases")
    for lease in leases.values():
        if type(lease) is not dict:
            raise ValueError("invalid scheduler lease")
        if lease.get("parent_lease_id"):
            if lease["parent_lease_id"] not in leases:
                raise ValueError("scheduler child has no parent")
            continue
        name = lease["lane"]
        if type(name) is not str or not name:
            raise ValueError("invalid scheduler lane")
        usage = lanes.setdefault(name, {"reservation": {}, "allocated": dict.fromkeys(used, 0)})["allocated"]
        for field in used:
            value = _integer(lease.get(field, 0), "scheduler lease " + field)
            used[field] += value
            usage[field] += value
    totals = {"cpu_slots": config.total_cpu_slots,
              "memory_mb": config.total_memory_mb - config.reserved_memory_mb,
              "child_process_slots": config.total_child_process_slots}
    return {"state_path": str(path), "read_only": True, "stale_leases_charged": True,
            "available": {name: max(0, totals[name] - used[name]) for name in used},
            "allocated": used, "lanes": lanes}


def capacity_plan(*, max_workers, memory_budget_mb, pending_count, cpu_budget=None,
                  per_worker_memory_mb=1024, per_worker_cpu=1, reserve_mb=512,
                  storage_headroom_bytes=None, per_worker_storage_bytes=0,
                  scheduler_available_cpu=None, scheduler_available_memory_mb=None,
                  scheduler_available_process_slots=None, per_worker_process_slots=1,
                  process_budget=None, reserve_process_slots=0,
                  probe=None):
    """Bound parallel passes by hardware, the caller's envelope, and headroom.

    ``memory_budget_mb`` is the whole group's existing reservation. For a fleet
    it is the maximum aggregate envelope. Scheduler limits are supplied only
    before acquiring root reservations; a nested caller supplies its parent's
    CPU/memory envelope instead. Zero capacity is a normal deferral.
    """
    for name, value, minimum in (("max_workers", max_workers, 1),
            ("memory_budget_mb", memory_budget_mb, 0), ("pending_count", pending_count, 0),
            ("per_worker_memory_mb", per_worker_memory_mb, 1), ("per_worker_cpu", per_worker_cpu, 1),
            ("reserve_mb", reserve_mb, 0), ("per_worker_storage_bytes", per_worker_storage_bytes, 0),
            ("reserve_process_slots", reserve_process_slots, 0),
            ("per_worker_process_slots", per_worker_process_slots, 1)):
        _integer(value, name, minimum)
    if max_workers > 32:
        raise ValueError("max_workers exceeds 32")
    for name, value in (("cpu_budget", cpu_budget), ("storage_headroom_bytes", storage_headroom_bytes),
            ("scheduler_available_cpu", scheduler_available_cpu),
            ("scheduler_available_memory_mb", scheduler_available_memory_mb),
            ("process_budget", process_budget),
            ("scheduler_available_process_slots", scheduler_available_process_slots)):
        if value is not None:
            _integer(value, name)
    observed = dict(hardware_probe() if probe is None else probe)
    limits = {"requested_workers": max_workers, "pending_passes": pending_count,
              "reservation_memory": max(0, memory_budget_mb - reserve_mb) // per_worker_memory_mb}
    reasons = []
    for name in ("hardware_cpu_count", "affinity_cpu_count", "cgroup_cpu_count"):
        value = observed.get(name)
        if value is None:
            if name == "hardware_cpu_count":
                limits[name] = 0
                reasons.append("unknown_cpu_capacity")
            continue
        if type(value) not in (int, float) or not math.isfinite(value) or value < 0:
            raise ValueError("invalid hardware probe " + name)
        limits[name] = math.floor(value / per_worker_cpu)
    for name in ("available_memory_mb", "cgroup_memory_remaining_mb"):
        value = observed.get(name)
        if value is None:
            if name == "available_memory_mb":
                limits[name] = 0
                reasons.append("unknown_available_memory")
            continue
        _integer(value, name)
        limits[name] = max(0, value - reserve_mb) // per_worker_memory_mb
    if observed.get("probe_errors"):
        limits["probe_health"] = 0
        reasons.append("hardware_probe_error")
    for name, value, cost in (("reservation_cpu", cpu_budget, per_worker_cpu),
            ("scheduler_cpu", scheduler_available_cpu, per_worker_cpu),
            ("scheduler_memory", scheduler_available_memory_mb, per_worker_memory_mb),
            ("reservation_process_slots", process_budget, per_worker_process_slots),
            ("scheduler_process_slots", scheduler_available_process_slots, per_worker_process_slots)):
        if value is not None:
            overhead = (reserve_mb if name == "scheduler_memory" else reserve_process_slots
                        if name in {"scheduler_process_slots", "reservation_process_slots"} else 0)
            limits[name] = max(0, value - overhead) // cost
    if per_worker_storage_bytes:
        limits["storage_headroom"] = 0 if storage_headroom_bytes is None else storage_headroom_bytes // per_worker_storage_bytes
        if storage_headroom_bytes is None:
            reasons.append("unknown_storage_headroom")
    workers = min(limits.values())
    if workers == 0:
        reasons.extend("insufficient_" + key for key, value in limits.items() if value == 0 and key != "pending_passes")
        if not pending_count:
            reasons.append("no_pending_passes")
    return {"schema_version": "autoencoder-dispatch-capacity/v1", "workers": workers,
            "limits": limits, "telemetry": observed, "reasons": sorted(set(reasons)),
            "scope": "concurrent_independent_passes", "admitted": False}


def execution_resource_policy(execution_mode):
    """Declared conservative estimates, not measured hard process maxima.

    The 2026-09-28 smoke sampled ~997 MiB per training worker and ~1,106
    MiB for owner qualification. Inference workers used ~890 MiB each while
    concurrent Lake descendants added ~444--551 MiB per pass. Estimates add
    headroom and retain owner/Lake space while up to two training workers stay
    resident. Receipts retain these assumptions; RSS remains polled separately.
    """
    if execution_mode == "training":
        return {"per_worker_memory_mb": 1152, "reserve_mb": 2048,
                "per_worker_process_slots": 1, "reserve_process_slots": 4,
                "scope": "resident_optimizer_workers_plus_owner_tracker_lake_lean"}
    if execution_mode == "inference":
        return {"per_worker_memory_mb": 1792, "reserve_mb": 512,
                "per_worker_process_slots": 3, "reserve_process_slots": 2,
                "scope": "parallel_model_lake_lean_plus_coordinator_tracker"}
    raise ValueError("unknown autoencoder execution mode")


def execution_envelope(execution_mode, workers):
    _integer(workers, "workers")
    if workers > 32:
        raise ValueError("workers exceeds 32")
    policy = execution_resource_policy(execution_mode)
    return {"execution_mode": execution_mode, "workers": workers,
            "estimated_memory_mb": policy["reserve_mb"] + workers * policy["per_worker_memory_mb"] if workers else 0,
            "cpu_slots": workers,
            "child_process_slots": policy["reserve_process_slots"] + workers * policy["per_worker_process_slots"] if workers else 0,
            "estimate_policy": policy, "scope": "cooperative_resource_estimate_not_kernel_quota"}


def execution_capacity_plan(execution_mode, **kwargs):
    """Plan a complete inference/training group, including nested proof work."""
    policy = execution_resource_policy(execution_mode)
    costs = {name: value for name, value in policy.items() if name != "scope"}
    if any(name in kwargs for name in costs):
        raise ValueError("execution resource estimates cannot be overridden implicitly")
    plan = capacity_plan(**kwargs, **costs)
    plan["execution_envelope"] = execution_envelope(execution_mode, plan["workers"])
    return plan

"""Incremental, mutation-tracked identities for modal autoencoder state.

The operational revision in this module answers "did this object mutate?" while
the deterministic digest answers "does this object contain the same persisted
state?".  Keeping those concepts separate makes save/reload identities stable
without allowing an asynchronous result to validate itself after its source
object has moved to a later revision.
"""

from __future__ import annotations

import copy
import hashlib
import json
import math
import threading
from dataclasses import asdict, dataclass, is_dataclass
from typing import Any, Callable, Dict, Iterable, Mapping, Optional, Sequence

from .modal_autoencoder_arrow_weights import MappedFeatureEmbeddingWeights


MODAL_AUTOENCODER_STATE_IDENTITY_SCHEMA_VERSION = "modal-autoencoder-incremental-state-identity-v1"


class StaleStateResultError(RuntimeError):
    """Raised when work produced for an older state revision is consumed."""


def _canonical_value(value: Any) -> Any:
    """Return a deterministic, strict-JSON representation of ``value``."""

    if value is None or isinstance(value, (str, bool, int)):
        return value
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError("state identity cannot contain a non-finite float")
        return value
    if isinstance(value, Mapping):
        return {
            str(key): _canonical_value(item)
            for key, item in sorted(value.items(), key=lambda pair: str(pair[0]))
        }
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        return [_canonical_value(item) for item in value]
    if is_dataclass(value):
        return _canonical_value(asdict(value))
    to_dict = getattr(value, "to_dict", None)
    if callable(to_dict):
        return _canonical_value(to_dict())
    raise TypeError(f"unsupported state identity value: {type(value).__name__}")


def canonical_digest(value: Any) -> str:
    """Hash a value using the repository's canonical strict-JSON convention."""

    payload = json.dumps(
        _canonical_value(value),
        allow_nan=False,
        ensure_ascii=True,
        separators=(",", ":"),
        sort_keys=True,
    ).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


class _TrackedDict(dict):
    """A normal dict whose successful mutations invalidate one component."""

    def __init__(
        self,
        value: Mapping[Any, Any],
        callback: Callable[[], None],
        before_callback: Callable[[tuple[Any, ...], str], None],
        path: tuple[Any, ...],
    ) -> None:
        self._callback = callback
        self._before_callback = before_callback
        self._path = path
        dict.__init__(
            self,
            (
                (
                    key,
                    _tracked_value(
                        item,
                        callback,
                        before_callback,
                        (*path, key),
                    ),
                )
                for key, item in value.items()
            ),
        )

    def __deepcopy__(self, memo: Dict[int, Any]) -> Dict[Any, Any]:
        return {copy.deepcopy(key, memo): copy.deepcopy(value, memo) for key, value in self.items()}

    def __setitem__(self, key: Any, value: Any) -> None:
        item_path = (*self._path, key)
        self._before_callback(item_path, "set")
        dict.__setitem__(
            self,
            key,
            _tracked_value(
                value,
                self._callback,
                self._before_callback,
                item_path,
            ),
        )
        self._callback()

    def __delitem__(self, key: Any) -> None:
        self._before_callback((*self._path, key), "delete")
        dict.__delitem__(self, key)
        self._callback()

    def clear(self) -> None:
        if self:
            for key in tuple(self):
                self._before_callback((*self._path, key), "delete")
            dict.clear(self)
            self._callback()

    def pop(self, key: Any, *default: Any) -> Any:
        existed = key in self
        if existed:
            self._before_callback((*self._path, key), "delete")
        result = dict.pop(self, key, *default)
        if existed:
            self._callback()
        return result

    def popitem(self) -> tuple[Any, Any]:
        if not self:
            return dict.popitem(self)
        key = next(reversed(self))
        self._before_callback((*self._path, key), "delete")
        result = dict.popitem(self)
        self._callback()
        return result

    def setdefault(self, key: Any, default: Any = None) -> Any:
        if key in self:
            return dict.__getitem__(self, key)
        item_path = (*self._path, key)
        self._before_callback(item_path, "insert")
        value = _tracked_value(
            default,
            self._callback,
            self._before_callback,
            item_path,
        )
        dict.__setitem__(self, key, value)
        self._callback()
        return value

    def update(self, *args: Any, **kwargs: Any) -> None:
        incoming = dict(*args, **kwargs)
        if not incoming:
            return
        for key, value in incoming.items():
            item_path = (*self._path, key)
            self._before_callback(item_path, "set")
            dict.__setitem__(
                self,
                key,
                _tracked_value(
                    value,
                    self._callback,
                    self._before_callback,
                    item_path,
                ),
            )
        self._callback()

    def __ior__(self, other: Mapping[Any, Any]) -> "_TrackedDict":
        self.update(other)
        return self


class _TrackedList(list):
    """A normal list whose successful mutations invalidate one component."""

    def __init__(
        self,
        value: Iterable[Any],
        callback: Callable[[], None],
        before_callback: Callable[[tuple[Any, ...], str], None],
        path: tuple[Any, ...],
    ) -> None:
        self._callback = callback
        self._before_callback = before_callback
        self._path = path
        list.__init__(
            self,
            (
                _tracked_value(
                    item,
                    callback,
                    before_callback,
                    (*path, index),
                )
                for index, item in enumerate(value)
            ),
        )

    def __deepcopy__(self, memo: Dict[int, Any]) -> list[Any]:
        return [copy.deepcopy(value, memo) for value in self]

    def __setitem__(self, index: Any, value: Any) -> None:
        self._before_callback((*self._path, index), "set")
        if isinstance(index, slice):
            wrapped = [
                _tracked_value(
                    item,
                    self._callback,
                    self._before_callback,
                    self._path,
                )
                for item in value
            ]
        else:
            wrapped = _tracked_value(
                value,
                self._callback,
                self._before_callback,
                (*self._path, index),
            )
        list.__setitem__(self, index, wrapped)
        self._callback()

    def __delitem__(self, index: Any) -> None:
        self._before_callback((*self._path, index), "delete")
        list.__delitem__(self, index)
        self._callback()

    def append(self, value: Any) -> None:
        index = len(self)
        self._before_callback((*self._path, index), "insert")
        list.append(
            self,
            _tracked_value(
                value,
                self._callback,
                self._before_callback,
                (*self._path, index),
            ),
        )
        self._callback()

    def extend(self, values: Iterable[Any]) -> None:
        raw_values = list(values)
        start = len(self)
        wrapped = [
            _tracked_value(
                value,
                self._callback,
                self._before_callback,
                (*self._path, start + offset),
            )
            for offset, value in enumerate(raw_values)
        ]
        if wrapped:
            self._before_callback(self._path, "extend")
            list.extend(self, wrapped)
            self._callback()

    def insert(self, index: int, value: Any) -> None:
        self._before_callback((*self._path, index), "insert")
        list.insert(
            self,
            index,
            _tracked_value(
                value,
                self._callback,
                self._before_callback,
                (*self._path, index),
            ),
        )
        self._callback()

    def pop(self, index: int = -1) -> Any:
        self._before_callback((*self._path, index), "delete")
        result = list.pop(self, index)
        self._callback()
        return result

    def remove(self, value: Any) -> None:
        self._before_callback((*self._path, self.index(value)), "delete")
        list.remove(self, value)
        self._callback()

    def clear(self) -> None:
        if self:
            self._before_callback(self._path, "clear")
            list.clear(self)
            self._callback()

    def reverse(self) -> None:
        if len(self) > 1:
            self._before_callback(self._path, "reorder")
            list.reverse(self)
            self._callback()

    def sort(self, *args: Any, **kwargs: Any) -> None:
        if len(self) > 1:
            self._before_callback(self._path, "reorder")
            list.sort(self, *args, **kwargs)
            self._callback()

    def __iadd__(self, values: Iterable[Any]) -> "_TrackedList":
        self.extend(values)
        return self

    def __imul__(self, count: int) -> "_TrackedList":
        before = list(self)
        if count != 1 and self:
            self._before_callback(self._path, "resize")
        list.__imul__(self, count)
        if list(self) != before:
            self._callback()
        return self


def _tracked_value(
    value: Any,
    callback: Callable[[], None],
    before_callback: Optional[Callable[[tuple[Any, ...], str], None]] = None,
    path: tuple[Any, ...] = (),
) -> Any:
    before = before_callback or (lambda _path, _operation: None)
    # Only this reviewed legacy component can retain mapped storage. It binds
    # the same before-mutation and dirty callbacks as ordinary containers;
    # arbitrary Mapping implementations still receive recursive tracking.
    if type(value) is MappedFeatureEmbeddingWeights:
        return value._bind_tracking(callback, before, path)
    if isinstance(value, Mapping):
        return _TrackedDict(value, callback, before, path)
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
        return _TrackedList(value, callback, before, path)
    return value


@dataclass(frozen=True, slots=True)
class StateIdentity:
    """A deterministic state identity plus its object-local revision."""

    digest: str
    revision: int
    schema_version: str
    state_schema_version: str
    metric_lineage_digest: str
    component_digests: Mapping[str, str]

    def to_dict(self) -> Dict[str, Any]:
        return {
            "component_digests": dict(sorted(self.component_digests.items())),
            "digest": self.digest,
            "metric_lineage_digest": self.metric_lineage_digest,
            "revision": self.revision,
            "schema_version": self.schema_version,
            "state_schema_version": self.state_schema_version,
        }


@dataclass(frozen=True, slots=True)
class StateRevisionToken:
    """A token used to reject results from an earlier object revision."""

    revision: int
    digest: str
    state_schema_version: str
    metric_lineage_digest: str


class IncrementalStateIdentity:
    """Track component mutations and recompute only dirty component digests."""

    def __init__(
        self,
        *,
        schema_version: str,
        metric_lineage: Any,
        components: Optional[Mapping[str, Any]] = None,
        component_normalizers: Optional[Mapping[str, Callable[[Any], Any]]] = None,
        before_mutation: Optional[Callable[[str, tuple[Any, ...], str], None]] = None,
    ) -> None:
        if not str(schema_version or "").strip():
            raise ValueError("schema_version must be non-empty")
        self._state_schema_version = str(schema_version)
        self._metric_lineage = copy.deepcopy(metric_lineage)
        self._normalizers = dict(component_normalizers or {})
        self._before_mutation = before_mutation
        self._components: Dict[str, Any] = {}
        self._component_digests: Dict[str, str] = {}
        self._dirty: set[str] = set()
        self._identity_cache: Dict[str, StateIdentity] = {}
        self._revision = 0
        self._component_recomputations = 0
        self._component_compute_counts: Dict[str, int] = {}
        self._identity_recomputations = 0
        self._lock = threading.RLock()
        for name, value in (components or {}).items():
            self._install(str(name), value, mutation=False)

    def _callback(self, name: str) -> Callable[[], None]:
        return lambda: self.dirty(name)

    def _before_callback(
        self,
        name: str,
    ) -> Callable[[tuple[Any, ...], str], None]:
        def notify(path: tuple[Any, ...], operation: str) -> None:
            listener = self._before_mutation
            if listener is not None:
                listener(name, path, operation)

        return notify

    def _install(self, name: str, value: Any, *, mutation: bool) -> Any:
        wrapped = _tracked_value(
            value,
            self._callback(name),
            self._before_callback(name),
        )
        with self._lock:
            self._components[name] = wrapped
            self._dirty.add(name)
            self._identity_cache.clear()
            if mutation:
                self._revision += 1
        return wrapped

    def track_component(self, name: str, value: Any, *, mutation: bool = True) -> Any:
        """Install and return a recursively tracked component value."""

        return self._install(str(name), value, mutation=mutation)

    def dirty(self, name: str, *, mutation: bool = True) -> None:
        with self._lock:
            if name not in self._components:
                raise KeyError(f"unknown state component: {name}")
            if mutation:
                self._revision += 1
            self._dirty.add(name)
            self._identity_cache.clear()

    @property
    def revision(self) -> int:
        with self._lock:
            return self._revision

    def restore_revision(self, revision: int) -> None:
        """Restore a durable operational revision after checkpoint loading.

        Revisions are deliberately not part of the deterministic state digest,
        but delta logs use them to reject missing, reordered, and stale
        segments.  A freshly constructed state starts at revision zero, so a
        verified checkpoint loader must be able to restore the persisted
        counter without pretending that every decoded field was a new
        mutation.
        """

        value = int(revision)
        if value < 0:
            raise ValueError("state revision must be non-negative")
        with self._lock:
            self._revision = value
            # Cached identities contain the object-local revision even though
            # their digest does not.  Rebuild them on the next request.
            self._identity_cache.clear()

    def transaction_checkpoint(self) -> Dict[str, Any]:
        """Capture the small identity bookkeeping needed for exact rollback."""

        with self._lock:
            return {
                "component_compute_counts": dict(self._component_compute_counts),
                "component_digests": dict(self._component_digests),
                "component_recomputations": self._component_recomputations,
                "dirty": set(self._dirty),
                "identity_cache": dict(self._identity_cache),
                "identity_recomputations": self._identity_recomputations,
                "revision": self._revision,
            }

    def restore_transaction_checkpoint(self, checkpoint: Mapping[str, Any]) -> None:
        """Restore identity bookkeeping after transactional row restoration."""

        with self._lock:
            self._component_compute_counts = dict(checkpoint["component_compute_counts"])
            self._component_digests = dict(checkpoint["component_digests"])
            self._component_recomputations = int(checkpoint["component_recomputations"])
            self._dirty = set(checkpoint["dirty"])
            self._identity_cache = dict(checkpoint["identity_cache"])
            self._identity_recomputations = int(checkpoint["identity_recomputations"])
            self._revision = int(checkpoint["revision"])

    def set_lineage(self, metric_lineage: Any) -> None:
        with self._lock:
            self._metric_lineage = copy.deepcopy(metric_lineage)
            self._identity_cache.clear()

    def _lineage(self, metric_lineage: Any) -> tuple[Any, str]:
        value = {
            "bound_metric_lineage": self._metric_lineage,
            "requested_metric_lineage": (
                self._metric_lineage if metric_lineage is None else metric_lineage
            ),
        }
        return value, canonical_digest(value)

    def component_digests(self) -> Dict[str, str]:
        with self._lock:
            dirty = tuple(sorted(self._dirty))
            for name in dirty:
                value = self._components[name]
                normalizer = self._normalizers.get(name)
                if normalizer is not None:
                    value = normalizer(value)
                self._component_digests[name] = canonical_digest(value)
                self._component_recomputations += 1
                self._component_compute_counts[name] = (
                    self._component_compute_counts.get(name, 0) + 1
                )
            self._dirty.difference_update(dirty)
            return dict(sorted(self._component_digests.items()))

    def identity(self, *, metric_lineage: Any = None) -> StateIdentity:
        lineage, lineage_digest = self._lineage(metric_lineage)
        with self._lock:
            cached = self._identity_cache.get(lineage_digest)
            if cached is not None and not self._dirty:
                return cached
            component_digests = self.component_digests()
            envelope = {
                "component_digests": component_digests,
                "identity_schema_version": MODAL_AUTOENCODER_STATE_IDENTITY_SCHEMA_VERSION,
                "metric_lineage": _canonical_value(lineage),
                "state_schema_version": self._state_schema_version,
            }
            identity = StateIdentity(
                digest=canonical_digest(envelope),
                revision=self._revision,
                schema_version=MODAL_AUTOENCODER_STATE_IDENTITY_SCHEMA_VERSION,
                state_schema_version=self._state_schema_version,
                metric_lineage_digest=lineage_digest,
                component_digests=component_digests,
            )
            self._identity_cache[lineage_digest] = identity
            self._identity_recomputations += 1
            return identity

    def digest(self, *, metric_lineage: Any = None) -> str:
        return self.identity(metric_lineage=metric_lineage).digest

    def token(self, *, metric_lineage: Any = None) -> StateRevisionToken:
        identity = self.identity(metric_lineage=metric_lineage)
        return StateRevisionToken(
            revision=identity.revision,
            digest=identity.digest,
            state_schema_version=identity.state_schema_version,
            metric_lineage_digest=identity.metric_lineage_digest,
        )

    def matches(self, token: StateRevisionToken, *, metric_lineage: Any = None) -> bool:
        if metric_lineage is None:
            with self._lock:
                if token.revision != self._revision or self._dirty:
                    return False
                cached = self._identity_cache.get(token.metric_lineage_digest)
                return bool(cached is not None and cached.digest == token.digest)
        current = self.token(metric_lineage=metric_lineage)
        return current == token

    def assert_current(self, token: StateRevisionToken, *, metric_lineage: Any = None) -> None:
        if not self.matches(token, metric_lineage=metric_lineage):
            current_revision = self.revision
            raise StaleStateResultError(
                "state result is stale: "
                f"current revision {current_revision}, "
                f"received revision {token.revision} ({token.digest})"
            )

    def stats(self) -> Dict[str, Any]:
        with self._lock:
            return {
                "component_count": len(self._components),
                "component_digest_compute_count": self._component_recomputations,
                "component_digest_compute_counts": dict(
                    sorted(self._component_compute_counts.items())
                ),
                "component_recomputations": self._component_recomputations,
                "dirty_component_count": len(self._dirty),
                "identity_recomputations": self._identity_recomputations,
                "revision": self._revision,
            }


__all__ = [
    "IncrementalStateIdentity",
    "MODAL_AUTOENCODER_STATE_IDENTITY_SCHEMA_VERSION",
    "StaleStateResultError",
    "StateIdentity",
    "StateRevisionToken",
    "canonical_digest",
]

"""Bounded, immutable sparse checkpoints over trusted content-addressed inputs.

A manifest contains only hashes, sizes and ordered accepted postimage patches.
The caller supplies the trusted hash-to-local-path resolver; artifacts cannot
choose paths, import classes or fetch a network resource. Each manifest edge is
one training job. Its parent undergoes normal JSON reload semantics (including
revision zero) before that job's patches, with no within-job revision rebasing.

Canonical checkpoint hashing uses the existing C-backed ``to_json`` encoding.
It avoids writing a full candidate, but still allocates its temporary JSON and
the dictionary used by ``to_dict``. This is sparse persistence, not zero-copy
checkpoint reconstruction. No publication, promotion or Lean admission occurs.
"""

from __future__ import annotations

from dataclasses import dataclass, is_dataclass, asdict
import hashlib
import json
import os
from pathlib import Path
import re
import stat
from typing import Any, Callable, Mapping

from .modal_autoencoder_patch_codec import (
    IDENTITY_PROFILE, MAX_PATCH_BYTES, PatchCodecError, decode_patch, replay_patch,
)


SCHEMA = "modal-autoencoder-sparse-checkpoint/v1"
RELOAD_SEMANTICS = "legacy-json-from-dict-revision-zero"
_SHA = re.compile(r"[0-9a-f]{64}\Z")


class SparseCheckpointError(ValueError):
    """Malformed, corrupt, untrusted, unsupported or over-budget checkpoint."""


@dataclass(frozen=True)
class ResolutionLimits:
    max_depth: int = 8
    max_manifest_bytes: int = 1024 * 1024
    max_checkpoint_bytes: int = 512 * 1024 * 1024
    max_patch_bytes: int = MAX_PATCH_BYTES
    max_total_patch_bytes: int = 256 * 1024 * 1024
    max_artifacts: int = 4096
    max_total_bytes: int = 4 * 1024 * 1024 * 1024

    def __post_init__(self) -> None:
        ceilings = {"max_depth": 64, "max_manifest_bytes": 16 * 1024 * 1024,
                    "max_checkpoint_bytes": 4 * 1024 * 1024 * 1024,
                    "max_patch_bytes": MAX_PATCH_BYTES,
                    "max_total_patch_bytes": 4 * 1024 * 1024 * 1024,
                    "max_artifacts": 65536, "max_total_bytes": 16 * 1024 * 1024 * 1024}
        for name, ceiling in ceilings.items():
            value = getattr(self, name)
            if type(value) is not int or not (0 if name == "max_depth" else 1) <= value <= ceiling:
                raise SparseCheckpointError(f"{name} exceeds its supported bound")


def _sha(value: Any, name: str) -> str:
    if not isinstance(value, str) or not _SHA.fullmatch(value):
        raise SparseCheckpointError(f"{name} must be a lowercase SHA-256")
    return value


def _int(value: Any, name: str, minimum: int = 0) -> int:
    if type(value) is not int or not minimum <= value < 2**63:
        raise SparseCheckpointError(f"{name} must be a bounded integer")
    return value


def artifact_ref(value: Any) -> dict[str, Any]:
    """Strip caller-owned path/metadata, retaining only immutable byte identity."""
    if is_dataclass(value) and not isinstance(value, type):
        value = asdict(value)
    if not isinstance(value, Mapping):
        raise SparseCheckpointError("artifact reference must be a mapping")
    return {"sha256": _sha(value.get("sha256"), "artifact.sha256"),
            "bytes": _int(value.get("bytes"), "artifact.bytes", 1)}


def _strict_ref(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict) or set(value) != {"sha256", "bytes"}:
        raise SparseCheckpointError("manifest artifact reference has unknown or missing fields")
    return artifact_ref(value)


def _json(value: Any) -> bytes:
    try:
        return json.dumps(value, ensure_ascii=True, allow_nan=False,
                          sort_keys=True, separators=(",", ":")).encode("utf-8")
    except (ValueError, TypeError, RecursionError, OverflowError) as exc:
        raise SparseCheckpointError("invalid bounded JSON value") from exc


def _unique(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise SparseCheckpointError("duplicate JSON field")
        result[key] = value
    return result


def _parse(raw: bytes) -> Any:
    try:
        return json.loads(raw, object_pairs_hook=_unique,
                          parse_constant=lambda _: (_ for _ in ()).throw(SparseCheckpointError("non-finite JSON")))
    except (UnicodeError, json.JSONDecodeError, RecursionError, OverflowError) as exc:
        raise SparseCheckpointError("invalid checkpoint JSON") from exc


def canonical_checkpoint_bytes(state: Any) -> bytes:
    """Exact existing candidate format, including its single trailing newline."""
    try:
        return (state.to_json() + "\n").encode("utf-8")
    except (ValueError, TypeError, RecursionError, OverflowError) as exc:
        raise SparseCheckpointError("checkpoint cannot be canonically serialized") from exc


def checkpoint_identity(state: Any) -> dict[str, Any]:
    """Hash canonical JSON without writing it; temporary full serialization remains."""
    raw = canonical_checkpoint_bytes(state)
    return {"sha256": hashlib.sha256(raw).hexdigest(), "bytes": len(raw)}


_FIELDS = {"schema", "schema_version", "identity_profile", "reload_semantics", "parent", "base_version_id",
           "patches", "materialized_checkpoint", "state_identity", "result_revision", "provenance"}


def _validate_manifest(value: Any, limits: ResolutionLimits) -> dict[str, Any]:
    if not isinstance(value, dict) or set(value) != _FIELDS:
        raise SparseCheckpointError("manifest has unknown or missing fields")
    if value["schema"] != SCHEMA or value["schema_version"] != SCHEMA or value["identity_profile"] != IDENTITY_PROFILE:
        raise SparseCheckpointError("unsupported sparse checkpoint schema or identity profile")
    if value["reload_semantics"] != RELOAD_SEMANTICS:
        raise SparseCheckpointError("unsupported checkpoint reload semantics")
    _strict_ref(value["parent"])
    if not isinstance(value["base_version_id"], str) or not 1 <= len(value["base_version_id"]) <= 256:
        raise SparseCheckpointError("base_version_id must be a bounded nonempty string")
    patches = value["patches"]
    if not isinstance(patches, list) or len(patches) > limits.max_artifacts:
        raise SparseCheckpointError("patch reference count exceeds bound")
    seen: set[str] = set()
    total = 0
    for patch in patches:
        ref = _strict_ref(patch)
        if ref["bytes"] > limits.max_patch_bytes:
            raise SparseCheckpointError("patch exceeds byte bound")
        if ref["sha256"] in seen:
            raise SparseCheckpointError("duplicate patch reference")
        seen.add(ref["sha256"])
        total += ref["bytes"]
    if total > limits.max_total_patch_bytes:
        raise SparseCheckpointError("total patch bytes exceed bound")
    if _strict_ref(value["materialized_checkpoint"])["bytes"] > limits.max_checkpoint_bytes:
        raise SparseCheckpointError("materialized checkpoint exceeds byte bound")
    _sha(value["state_identity"], "state_identity")
    _int(value["result_revision"], "result_revision")
    if not isinstance(value["provenance"], dict):
        raise SparseCheckpointError("provenance must be a JSON object")
    if not patches and value["result_revision"] != 0:
        raise SparseCheckpointError("empty job cannot advance the reload revision")
    return value


def encode_manifest(*, parent: Any, base_version_id: str, patches: Any,
                    materialized_checkpoint: Any, state_identity: str,
                    result_revision: int, provenance: Mapping[str, Any] | None = None,
                    limits: ResolutionLimits = ResolutionLimits()) -> bytes:
    """Encode an immutable job manifest; replay qualification remains mandatory."""
    # Legacy full-state loaders inspect schema_version. Keep this additional
    # marker mandatory so they reject a sparse manifest instead of silently
    # normalizing its unknown fields into an empty/default full model.
    value = {"schema": SCHEMA, "schema_version": SCHEMA, "identity_profile": IDENTITY_PROFILE,
             "reload_semantics": RELOAD_SEMANTICS, "parent": artifact_ref(parent),
             "base_version_id": base_version_id, "patches": [artifact_ref(patch) for patch in patches],
             "materialized_checkpoint": artifact_ref(materialized_checkpoint),
             "state_identity": state_identity, "result_revision": result_revision,
             "provenance": dict(provenance or {})}
    raw = _json(_validate_manifest(value, limits))
    if len(raw) > limits.max_manifest_bytes:
        raise SparseCheckpointError("manifest exceeds byte bound")
    # Reparse to reject non-string keys that JSON would silently normalize.
    if _parse(raw) != value:
        raise SparseCheckpointError("manifest contains noncanonical JSON values")
    return raw


def decode_manifest(raw: bytes, *, limits: ResolutionLimits = ResolutionLimits()) -> dict[str, Any]:
    if not isinstance(raw, bytes) or not 0 < len(raw) <= limits.max_manifest_bytes:
        raise SparseCheckpointError("manifest must be bounded nonempty bytes")
    value = _validate_manifest(_parse(raw), limits)
    if _json(value) != raw:
        raise SparseCheckpointError("manifest is not canonically encoded")
    return value


@dataclass(frozen=True)
class ResolvedCheckpoint:
    state: Any
    materialized_checkpoint: Mapping[str, Any]
    state_identity: str
    replayed_revision: int
    depth: int
    total_patch_bytes: int
    manifest: Mapping[str, Any] | None
    anchor_checkpoint: Mapping[str, Any]
    artifacts: tuple[Mapping[str, Any], ...]

    @property
    def anchor_checkpoint_bytes(self) -> int:
        return self.anchor_checkpoint["bytes"]


@dataclass(frozen=True)
class CheckpointInventory:
    """Verified artifact structure, explicitly not a reconstructed candidate.

    Sparse ``declared_materialized_checkpoint`` bytes and logical identities
    remain declarations until ``resolve_checkpoint`` replays the weights. A
    legacy full root retains its original, verified physical byte identity.
    """

    root: Mapping[str, Any]
    declared_materialized_checkpoint: Mapping[str, Any]
    depth: int
    total_patch_bytes: int
    total_bytes: int
    manifest: Mapping[str, Any] | None
    anchor_checkpoint: Mapping[str, Any]
    artifacts: tuple[Mapping[str, Any], ...]

    @property
    def semantic_replay_verified(self) -> bool:
        return False

    @property
    def weights_constructed(self) -> bool:
        return False


def _validate_legacy_inventory(data: Any) -> None:
    """Check legacy framing without normalizing or constructing model weights.

    Nested component value semantics deliberately remain the full loader's
    responsibility. JSON syntax, duplicate fields and nonfinite values have
    already been checked; this inventories the known top-level state schema.
    """
    from .modal_autoencoder import (
        MODAL_AUTOENCODER_COMPATIBLE_ARCHITECTURE_VERSIONS,
        MODAL_AUTOENCODER_LEGACY_ARCHITECTURE_VERSION,
        MODAL_AUTOENCODER_STATE_SERIALIZED_FIELDS,
        MODAL_AUTOENCODER_STATE_SCHEMA_VERSION,
    )

    if not isinstance(data, dict):
        raise SparseCheckpointError("checkpoint must be a JSON object")
    if str(data.get("schema_version") or MODAL_AUTOENCODER_STATE_SCHEMA_VERSION) != MODAL_AUTOENCODER_STATE_SCHEMA_VERSION:
        raise SparseCheckpointError("inventory supports qualified legacy JSON checkpoint schema only")
    if str(data.get("architecture_version") or MODAL_AUTOENCODER_LEGACY_ARCHITECTURE_VERSION) not in MODAL_AUTOENCODER_COMPATIBLE_ARCHITECTURE_VERSIONS:
        raise SparseCheckpointError("unsupported legacy checkpoint architecture")
    if set(data) - MODAL_AUTOENCODER_STATE_SERIALIZED_FIELDS:
        raise SparseCheckpointError("full checkpoint contains unknown fields")


def _read_artifact(path: Any, ref: Mapping[str, Any], maximum: int) -> bytes:
    if ref["bytes"] > maximum:
        raise SparseCheckpointError("artifact exceeds byte bound")
    try:
        candidate = Path(path)
        if not candidate.is_absolute():
            raise SparseCheckpointError("trusted resolver must return an absolute local path")
        fd = os.open(candidate, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        with os.fdopen(fd, "rb") as stream:
            info = os.fstat(stream.fileno())
            if not stat.S_ISREG(info.st_mode) or info.st_size != ref["bytes"]:
                raise SparseCheckpointError("artifact is not a regular file of the declared size")
            raw = stream.read(ref["bytes"] + 1)
    except (OSError, TypeError) as exc:
        raise SparseCheckpointError("trusted artifact could not be read") from exc
    if len(raw) != ref["bytes"] or hashlib.sha256(raw).hexdigest() != ref["sha256"]:
        raise SparseCheckpointError("artifact byte identity mismatch")
    return raw


def inventory_checkpoint(reference: Any, *, resolver: Callable[[Mapping[str, Any]], Any],
                         limits: ResolutionLimits = ResolutionLimits()) -> CheckpointInventory:
    """Verify a bounded immutable closure without reconstructing model weights.

    This checks every file's bytes, closed manifest and patch schemas, ordered
    segment bindings, job-local revision continuity and manifest provenance.
    It does not replay before/postimages, recompute model identities or verify
    the declared materialized checkpoint bytes. Use ``resolve_checkpoint`` in
    workers and at owner acceptance for those mandatory semantic checks.

    Legacy JSON is still parsed into ordinary Python data to validate its
    framing. No tracked state, copy-on-write overlay or full candidate JSON is
    constructed here, and the inventory does not cache trust between calls.
    """
    seen: dict[str, dict[str, Any]] = {}
    active: set[str] = set()
    total_bytes = 0
    patch_bytes = 0

    def read(ref: dict[str, Any], maximum: int) -> bytes:
        nonlocal total_bytes
        previous = seen.get(ref["sha256"])
        if previous is not None and previous != ref:
            raise SparseCheckpointError("same artifact digest has inconsistent sizes")
        if previous is None:
            if len(seen) >= limits.max_artifacts:
                raise SparseCheckpointError("artifact closure count exceeds bound")
            total_bytes += ref["bytes"]
            if total_bytes > limits.max_total_bytes:
                raise SparseCheckpointError("artifact closure bytes exceed bound")
            seen[ref["sha256"]] = ref
        try:
            path = resolver(dict(ref))
        except (KeyError, ValueError, OSError) as exc:
            raise SparseCheckpointError("artifact missing from trusted resolver") from exc
        return _read_artifact(path, ref, maximum)

    def visit(ref: dict[str, Any], ancestry: int) -> CheckpointInventory:
        nonlocal patch_bytes
        if ref["sha256"] in active:
            raise SparseCheckpointError("checkpoint parent cycle detected")
        if ancestry > limits.max_depth:
            raise SparseCheckpointError("checkpoint manifest depth exceeds bound")
        active.add(ref["sha256"])
        try:
            raw = read(ref, max(limits.max_checkpoint_bytes, limits.max_manifest_bytes))
            data = _parse(raw)
            if not isinstance(data, dict):
                raise SparseCheckpointError("checkpoint must be a JSON object")
            if data.get("schema") == SCHEMA:
                manifest = decode_manifest(raw, limits=limits)
                if ancestry == limits.max_depth:
                    raise SparseCheckpointError("checkpoint manifest depth exceeds bound")
                parent = visit(manifest["parent"], ancestry + 1)
                previous_identity = None
                previous_revision = 0
                for sequence, patch_ref in enumerate(manifest["patches"]):
                    patch_bytes += patch_ref["bytes"]
                    if patch_bytes > limits.max_total_patch_bytes:
                        raise SparseCheckpointError("total patch bytes exceed bound")
                    try:
                        segment = decode_patch(read(patch_ref, limits.max_patch_bytes))
                    except PatchCodecError as exc:
                        raise SparseCheckpointError(f"invalid inventory patch: {exc}") from exc
                    if segment.sequence != sequence or segment.base_version_id != manifest["base_version_id"]:
                        raise SparseCheckpointError("inventory patch sequence or base version mismatch")
                    if segment.patch.base_revision != previous_revision:
                        raise SparseCheckpointError("inventory patch base revision mismatch")
                    if previous_identity is not None and segment.base_state_identity != previous_identity:
                        raise SparseCheckpointError("inventory patch identity chain mismatch")
                    for name in ("job_id", "run_id", "job_spec_sha256"):
                        if name in manifest["provenance"] and segment.provenance.get(name) != manifest["provenance"][name]:
                            raise SparseCheckpointError(f"patch provenance mismatch: {name}")
                    previous_revision = segment.patch.result_revision
                    previous_identity = segment.result_state_identity
                if previous_revision != manifest["result_revision"]:
                    raise SparseCheckpointError("inventory manifest result revision mismatch")
                if previous_identity is not None and previous_identity != manifest["state_identity"]:
                    raise SparseCheckpointError("inventory manifest result identity mismatch")
                depth = parent.depth + 1
                materialized = manifest["materialized_checkpoint"]
                anchor = parent.anchor_checkpoint
            else:
                if ref["bytes"] > limits.max_checkpoint_bytes:
                    raise SparseCheckpointError("full checkpoint exceeds byte bound")
                _validate_legacy_inventory(data)
                manifest = None
                depth = 0
                materialized = ref
                anchor = ref
            return CheckpointInventory(dict(ref), dict(materialized), depth, patch_bytes, total_bytes,
                                       manifest, dict(anchor), tuple(seen.values()))
        finally:
            active.remove(ref["sha256"])

    return visit(artifact_ref(reference), 0)


def resolve_checkpoint(reference: Any, *, resolver: Callable[[Mapping[str, Any]], Any],
                       limits: ResolutionLimits = ResolutionLimits(),
                       reset_revision: bool = True) -> ResolvedCheckpoint:
    """Verify a complete bounded closure and reconstruct its exact candidate.

    Full legacy roots preserve their physical file byte identity for bindings
    such as Arrow. Sparse manifests declare canonical materialized bytes. The
    default returned state is normal ``from_dict`` reload state (revision zero);
    ``reset_revision=False`` preserves terminal patch revision for owner checks.
    """
    from .modal_autoencoder import (
        MODAL_AUTOENCODER_STATE_SERIALIZED_FIELDS, ModalAutoencoderTrainingState,
    )

    if type(reset_revision) is not bool:
        raise SparseCheckpointError("reset_revision must be boolean")
    seen: dict[str, dict[str, Any]] = {}
    active: set[str] = set()
    total_bytes = 0
    patch_bytes = 0

    def read(ref: dict[str, Any], maximum: int) -> bytes:
        nonlocal total_bytes
        previous = seen.get(ref["sha256"])
        if previous is not None and previous != ref:
            raise SparseCheckpointError("same artifact digest has inconsistent sizes")
        if previous is None:
            if len(seen) >= limits.max_artifacts:
                raise SparseCheckpointError("artifact closure count exceeds bound")
            total_bytes += ref["bytes"]
            if total_bytes > limits.max_total_bytes:
                raise SparseCheckpointError("artifact closure bytes exceed bound")
            seen[ref["sha256"]] = ref
        try:
            path = resolver(dict(ref))
        except (KeyError, ValueError, OSError) as exc:
            raise SparseCheckpointError("artifact missing from trusted resolver") from exc
        return _read_artifact(path, ref, maximum)

    def visit(ref: dict[str, Any], ancestry: int, reload_result: bool) -> ResolvedCheckpoint:
        nonlocal patch_bytes
        if ref["sha256"] in active:
            raise SparseCheckpointError("checkpoint parent cycle detected")
        if ancestry > limits.max_depth:
            raise SparseCheckpointError("checkpoint manifest depth exceeds bound")
        active.add(ref["sha256"])
        try:
            raw = read(ref, max(limits.max_checkpoint_bytes, limits.max_manifest_bytes))
            data = _parse(raw)
            if not isinstance(data, dict):
                raise SparseCheckpointError("checkpoint must be a JSON object")
            if data.get("schema") == SCHEMA:
                manifest = decode_manifest(raw, limits=limits)
                if ancestry == limits.max_depth:
                    raise SparseCheckpointError("checkpoint manifest depth exceeds bound")
                parent = visit(manifest["parent"], ancestry + 1, True)
                state = parent.state
                for sequence, patch_ref in enumerate(manifest["patches"]):
                    patch_bytes += patch_ref["bytes"]
                    if patch_bytes > limits.max_total_patch_bytes:
                        raise SparseCheckpointError("total patch bytes exceed bound")
                    patch_raw = read(patch_ref, limits.max_patch_bytes)
                    try:
                        segment = decode_patch(patch_raw)
                        for name in ("job_id", "run_id", "job_spec_sha256"):
                            if name in manifest["provenance"] and segment.provenance.get(name) != manifest["provenance"][name]:
                                raise SparseCheckpointError(f"patch provenance mismatch: {name}")
                        replay_patch(state, segment, expected_base_version_id=manifest["base_version_id"],
                                     expected_sequence=sequence)
                    except PatchCodecError as exc:
                        raise SparseCheckpointError(f"sparse checkpoint patch replay failed: {exc}") from exc
                replayed_revision = state.state_revision
                identity = state.state_identity()
                if replayed_revision != manifest["result_revision"] or identity != manifest["state_identity"]:
                    raise SparseCheckpointError("manifest result state identity or revision mismatch")
                if checkpoint_identity(state) != manifest["materialized_checkpoint"]:
                    raise SparseCheckpointError("manifest materialized checkpoint byte identity mismatch")
                depth = parent.depth + 1
                materialized = manifest["materialized_checkpoint"]
                anchor = parent.anchor_checkpoint
                if reload_result:
                    state = ModalAutoencoderTrainingState.from_dict(state.to_dict())
            else:
                if ref["bytes"] > limits.max_checkpoint_bytes:
                    raise SparseCheckpointError("full checkpoint exceeds byte bound")
                if str(data.get("schema_version", "")).startswith("modal-autoencoder-tensor-state-"):
                    raise SparseCheckpointError("sparse resolver supports qualified legacy JSON checkpoints only")
                try:
                    state = ModalAutoencoderTrainingState.from_dict(data)
                except (ValueError, TypeError, KeyError, OverflowError) as exc:
                    raise SparseCheckpointError("invalid full legacy checkpoint") from exc
                if set(data) - MODAL_AUTOENCODER_STATE_SERIALIZED_FIELDS:
                    raise SparseCheckpointError("full checkpoint contains unknown fields")
                manifest = None
                replayed_revision = 0
                identity = state.state_identity()
                depth = 0
                materialized = ref
                anchor = ref
            return ResolvedCheckpoint(state, dict(materialized), identity, replayed_revision, depth,
                                      patch_bytes, manifest, dict(anchor), tuple(seen.values()))
        finally:
            active.remove(ref["sha256"])

    return visit(artifact_ref(reference), 0, reset_revision)


def write_checkpoint(state: Any, destination: str | Path, *,
                     expected_identity: Mapping[str, Any] | None = None) -> dict[str, Any]:
    """Explicit exclusive full materialization, with a temporary full JSON buffer."""
    raw = canonical_checkpoint_bytes(state)
    identity = {"sha256": hashlib.sha256(raw).hexdigest(), "bytes": len(raw)}
    if expected_identity is not None and identity != artifact_ref(expected_identity):
        raise SparseCheckpointError("materialization differs from expected canonical checkpoint")
    path = Path(destination)
    with path.open("xb") as stream:
        stream.write(raw)
        stream.flush()
        os.fsync(stream.fileno())
    return {"path": str(path.absolute()), **identity}


def materialize_checkpoint(resolved: ResolvedCheckpoint, destination: str | Path) -> dict[str, Any]:
    """Write a verified sparse candidate or canonicalize a legacy full anchor.

    Resolve sparse candidates with ``reset_revision=False`` before compaction:
    this preserves the exact terminal candidate even if JSON reload normalizes
    a component. Default reloaded results are rejected if canonical bytes differ.
    """
    expected = resolved.materialized_checkpoint if resolved.manifest is not None else None
    return write_checkpoint(resolved.state, destination, expected_identity=expected)


__all__ = ["SCHEMA", "RELOAD_SEMANTICS", "SparseCheckpointError", "ResolutionLimits",
           "ResolvedCheckpoint", "CheckpointInventory", "artifact_ref", "canonical_checkpoint_bytes", "checkpoint_identity",
           "encode_manifest", "decode_manifest", "inventory_checkpoint", "resolve_checkpoint", "write_checkpoint", "materialize_checkpoint"]

scripts/ops/legal_ir/run_autoencoder_fle:
#!/usr/bin/env python3
"""Bounded waves of existing, preconfigured distributed autoencoder workers.

The fleet plans capacity, preserves worker state and owns child lifecycles. The
existing worker remains responsible for reservations, source pins, qualifications
and publication. Synchronization is explicit; it is not inference or admission.
"""
from __future__ import annotations

import argparse
from contextlib import contextmanager
import fcntl
import hashlib
import json
import math
import os
from pathlib import Path
import re
import shutil
import signal
import stat
import subprocess
import sys
import tempfile
import time
import uuid

ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(ROOT))
RUNNER = ROOT / "scripts/ops/legal_ir/run_distributed_autoencoders.py"
DEFAULT_LEDGER = ROOT / "workspace/test-logs/federal-corpus-audits/owned-daemon-resource-control/disk-reservations.json"
SCHEMA = "autoencoder-fleet/v1"
MAX_JSON_BYTES = 8 * 1024 * 1024
MAX_LOG_BYTES = 8 * 1024 * 1024
SAFE_ID = re.compile(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,63}\Z")


class FleetError(ValueError):
    pass


def _path(value):
    path = Path(os.path.abspath(os.fspath(value)))
    for component in [*reversed(path.parents), path]:
        if component.is_symlink():
            raise FleetError("fleet paths cannot contain symlinks")
    return path


def _read(path, maximum=MAX_JSON_BYTES):
    path = _path(path)
    descriptor = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    with os.fdopen(descriptor, "rb") as handle:
        info = os.fstat(handle.fileno())
        if not stat.S_ISREG(info.st_mode) or info.st_size > maximum:
            raise FleetError("expected bounded regular JSON file")
        raw = handle.read(maximum + 1)
    if len(raw) > maximum:
        raise FleetError("JSON byte limit exceeded")
    def pairs(values):
        result = {}
        for key, value in values:
            if key in result:
                raise FleetError("duplicate JSON field")
            result[key] = value
        return result
    result = json.loads(raw, object_pairs_hook=pairs,
                        parse_constant=lambda _: (_ for _ in ()).throw(FleetError("nonfinite JSON")))
    if not isinstance(result, dict):
        raise FleetError("JSON object required")
    return result


def _write(path, value):
    path = _path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    raw = (json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False) + "\n").encode()
    if len(raw) > MAX_JSON_BYTES:
        raise FleetError("fleet receipt exceeds bound")
    with tempfile.NamedTemporaryFile(dir=path.parent, prefix=".fleet-", delete=False) as handle:
        temporary = Path(handle.name)
        handle.write(raw)
        handle.flush()
        os.fsync(handle.fileno())
    try:
        os.replace(temporary, path)
        descriptor = os.open(path.parent, os.O_RDONLY | os.O_DIRECTORY)
        try:
            os.fsync(descriptor)
        finally:
            os.close(descriptor)
    finally:
        temporary.unlink(missing_ok=True)


def connections(paths, state_directory):
    rows, ids, tokens, campaigns = [], set(), set(), set()
    for path in paths:
        path = _path(path)
        value = _read(path, 64 * 1024)
        worker, campaign = value.get("worker_id"), value.get("campaign_id")
        if not isinstance(worker, str) or not SAFE_ID.fullmatch(worker) or not isinstance(campaign, str) or not SAFE_ID.fullmatch(campaign):
            raise FleetError("connection requires safe existing worker and campaign IDs")
        token = _path(value["token_file"])
        info = token.stat()
        if not stat.S_ISREG(info.st_mode) or info.st_mode & 0o077 or not 0 < info.st_size <= 1024:
            raise FleetError("connection token must be a private bounded regular file")
        if worker in ids or token in tokens:
            raise FleetError("duplicate worker identity or token file")
        ids.add(worker); tokens.add(token); campaigns.add(campaign)
        rows.append({"worker_id": worker, "campaign_id": campaign, "connection_file": str(path),
                     "state_directory": str(_path(state_directory) / "workers" / worker)})
    if not 1 <= len(rows) <= 32 or len(campaigns) != 1:
        raise FleetError("configure one to 32 unique identities from one existing campaign")
    return sorted(rows, key=lambda row: row["worker_id"])


def read_campaign(row):
    """Read the preconfigured owner; do not initialize a journal or claim work."""
    from ipfs_datasets_py.duckdb_control.autoencoder_span_campaign import SpanCampaignTransportClient
    value = _read(row["connection_file"], 64 * 1024)
    if any(value.get(key) != row[key] for key in ("worker_id", "campaign_id")):
        raise FleetError("connection identity changed")
    token_path = _path(value["token_file"])
    info = token_path.stat()
    if info.st_mode & 0o077 or not stat.S_ISREG(info.st_mode) or not 0 < info.st_size <= 1024:
        raise FleetError("connection token must remain a private bounded regular file")
    try:
        with SpanCampaignTransportClient(value["endpoint"], token_path.read_text().strip()) as client:
            result = client.request("ReadCampaign", {}, uuid.uuid4().hex, timeout=30)
    except Exception as exc:
        raise FleetError("owner read failed (" + type(exc).__name__ + ")") from None
    if result.get("campaign_id") != row["campaign_id"] or row["worker_id"] not in result.get("known_workers", []):
        raise FleetError("worker is not preconfigured in this campaign")
    return result


def storage_capacity(ledger_path, state_directory):
    """Observe existing shared roots and retained claims without modifying them."""
    from ipfs_datasets_py.optimizers.logic_theorem_optimizer import autoencoder_daemon_resources as resources
    raw = _read(ledger_path)
    roots = [row["path"] for row in raw["roots"]]
    state = _path(state_directory)
    if not any(state == _path(root) or _path(root) in state.parents for root in roots):
        raise FleetError("fleet state must be under an existing shared resource root")
    observer = resources.DaemonResourceReservation(ledger_path, roots=roots, storage_bytes=1, memory_mb=1)
    ledger = observer._read()
    observed = resources._inventory(observer.roots)["apparent_bytes"]
    outstanding = sum(row["storage_bytes"] for row in ledger["reservations"].values() if row["status"] != "released")
    free = min(shutil.disk_usage(root).free for root in observer.roots)
    return {"headroom_bytes": max(0, min(ledger["limit_bytes"] - observed - outstanding, free - outstanding)),
            "observed_apparent_bytes": observed, "outstanding_reservations_bytes": outstanding,
            "minimum_filesystem_free_bytes": free, "limit_bytes": ledger["limit_bytes"],
            "ledger_modified": False, "reservation_acquired": False}


def plan_wave(args, rows, *, campaign_reader=read_campaign, storage_reader=storage_capacity,
              capacity=None, scheduler_reader=None):
    from ipfs_datasets_py.optimizers.logic_theorem_optimizer import autoencoder_capacity as sizing
    capacity = capacity or sizing.capacity_plan
    campaigns = [campaign_reader(row) for row in rows]
    binding = campaigns[0]["binding_sha256"]
    if any(value.get("binding_sha256") != binding for value in campaigns):
        raise FleetError("worker connections do not share one campaign binding")
    policy = campaigns[0]["policy"]
    inner_storage = policy.get("worker_storage_bytes", 750_000_000)
    inner_memory = policy.get("memory_mb", 8192)
    if type(inner_storage) is not int or not 1 <= inner_storage <= 50_000_000_000 or type(inner_memory) is not int or inner_memory < 8192:
        raise FleetError("unsupported owner worker resource policy")
    if args.training_storage_bytes < inner_storage and not args.sync_only:
        raise FleetError("configured training storage understates the owner policy")
    storage = storage_reader(args.resource_ledger, args.state_directory)
    scheduler = scheduler_reader() if scheduler_reader is not None else sizing.scheduler_snapshot()
    available = sizing.scheduler_capacity(scheduler)
    memory = 1024 if args.sync_only else 1024 + inner_memory
    cpu = 1 if args.sync_only else 2
    # The outer control process and inner coordinator reserve independently.
    # The inner envelope includes its model pool and serial Lake/Lean work.
    processes = 1 if args.sync_only else 1 + sizing.execution_envelope("training", 1)["child_process_slots"]
    per_storage = args.worker_storage_bytes + (0 if args.sync_only else args.training_storage_bytes)
    limit = min(len(rows), args.max_workers or 32)
    planned = capacity(max_workers=limit, memory_budget_mb=args.memory_budget_mb,
        pending_count=limit if args.sync_only or args.pending_jobs is None else args.pending_jobs, cpu_budget=args.cpu_budget,
        per_worker_memory_mb=memory, per_worker_cpu=cpu, reserve_mb=0,
        storage_headroom_bytes=storage["headroom_bytes"], per_worker_storage_bytes=per_storage,
        scheduler_available_cpu=available["cpu_slots"], scheduler_available_memory_mb=available["memory_mb"],
        scheduler_available_process_slots=available["child_process_slots"], per_worker_process_slots=processes)
    return {"schema": SCHEMA, "intent": "synchronize_weights" if args.sync_only else "train_one_span_per_worker",
            "campaign_id": rows[0]["campaign_id"], "campaign_binding_sha256": binding,
            "configured_worker_ids": [row["worker_id"] for row in rows], "capacity": planned,
            "per_worker": {"memory_mb": memory, "cpu_slots": cpu, "child_process_slots": processes,
                           "storage_bytes": per_storage},
            "storage": storage, "scheduler_available": available, "owner_generation": campaigns[0]["weights"]["generation"],
            "admitted": False, "formalized": False, "reservation_acquired": False}


@contextmanager
def exclusive(path):
    path = _path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    descriptor = os.open(path, os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
    try:
        info = os.fstat(descriptor)
        if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
            raise FleetError("lock must be an unaliased regular file")
        fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
        yield descriptor
    finally:
        os.close(descriptor)


def worker_command(args, row):
    command = [sys.executable, str(RUNNER), "worker", "--connection-file", row["connection_file"],
               "--state-directory", row["state_directory"], "--resource-ledger", str(args.resource_ledger),
               "--storage-bytes", str(args.worker_storage_bytes), "--polls", "1", "--max-jobs", "1",
               "--lease-seconds", str(args.lease_seconds)]
    if args.sync_only:
        command.append("--sync-only")
    return command


def process_snapshot():
    from ipfs_datasets_py.optimizers.logic_theorem_optimizer.autoencoder_daemon_resources import _process
    entries = list(Path("/proc").iterdir())
    if len(entries) > 100_000:
        raise FleetError("process inventory exceeds bound")
    return {int(path.name): value for path in entries if path.name.isdecimal()
            if (value := _process(int(path.name))) is not None}


def collect_owned(known, snapshot):
    live = {pid for pid, birth in known.items() if pid in snapshot and snapshot[pid]["birth"] == birth}
    while True:
        extra = {pid for pid, row in snapshot.items() if row["parent_pid"] in live}
        if extra <= live:
            break
        live.update(extra)
    known.update({pid: snapshot[pid]["birth"] for pid in live})
    return {pid: snapshot[pid] for pid in live if snapshot[pid]["state"] != "Z"}


def stop_owned(process, known, *, grace_seconds=5):
    """Signal verified PID births only; descendants may own separate sessions."""
    for sig, deadline in ((signal.SIGTERM, grace_seconds), (signal.SIGKILL, 5)):
        live = collect_owned(known, process_snapshot())
        for pid in sorted(live, reverse=True):
            current = process_snapshot().get(pid)
            if current is not None and current["birth"] == known[pid]:
                try:
                    os.kill(pid, sig)
                except ProcessLookupError:
                    pass
        end = time.monotonic() + deadline
        while time.monotonic() < end:
            process.poll()
            for pid in known:
                if pid != process.pid:
                    try:
                        os.waitpid(pid, os.WNOHANG)
                    except ChildProcessError:
                        pass
            if not collect_owned(known, process_snapshot()):
                break
            time.sleep(0.05)
    process.wait(timeout=5)
    if collect_owned(known, process_snapshot()):
        raise FleetError("owned descendants remain live after bounded shutdown")


def run_wave(args, selected, directory, stop, *, popen=subprocess.Popen):
    # Detached grandchildren reparent here when an owned coordinator exits.
    # This dedicated launcher reaps only descendants whose PID birth it recorded.
    import ctypes
    if ctypes.CDLL(None, use_errno=True).prctl(36, 1, 0, 0, 0) != 0:
        raise FleetError("Linux child-subreaper setup failed")
    directory.mkdir(parents=True, exist_ok=False)
    receipt = {"schema": SCHEMA, "workers": [], "started_at": time.time(), "admitted": False}
    active = []
    try:
        for row in selected:
            if stop[0]:
                break
            key = hashlib.sha256((row["campaign_id"] + ":" + row["worker_id"]).encode()).hexdigest()
            guard = exclusive(args.resource_ledger.parent / "fleet-identity-locks" / (key + ".lock"))
            try:
                descriptor = guard.__enter__()
            except BlockingIOError:
                receipt["workers"].append({"worker_id": row["worker_id"], "status": "identity_busy"})
                continue
            log_path = directory / (row["worker_id"] + ".log")
            handle = None
            status_path = Path(row["state_directory"]) / "worker-status.json"
            before_status = status_path.stat() if status_path.exists() else None
            try:
                handle = open(log_path, "xb", opener=lambda path, flags: os.open(path, flags, 0o600))
                process = popen(worker_command(args, row), stdin=subprocess.DEVNULL, stdout=handle,
                    stderr=subprocess.STDOUT, shell=False, start_new_session=True, pass_fds=(descriptor,))
            except BaseException:
                if handle is not None:
                    handle.close()
                guard.__exit__(None, None, None)
                raise
            from ipfs_datasets_py.optimizers.logic_theorem_optimizer.autoencoder_daemon_resources import _process
            identity = _process(process.pid)
            if identity is None:
                process.wait(timeout=5)
                known = {}
            else:
                known = {process.pid: identity["birth"]}
            entry = {"worker_id": row["worker_id"], "pid": process.pid, "status": "running",
                     "log_path": str(log_path), "owned_processes": known,
                     "status_inode_before": None if before_status is None else [before_status.st_ino, before_status.st_mtime_ns]}
            receipt["workers"].append(entry)
            active.append((process, known, handle, guard, entry, row))
            _write(directory / "wave.json", receipt)
        started = time.monotonic()
        while active:
            snapshot = process_snapshot()
            for process, known, handle, guard, entry, row in list(active):
                collect_owned(known, snapshot)
                reason = "interrupted" if stop[0] else "timeout" if time.monotonic() - started >= args.wave_timeout else "log_limit" if Path(entry["log_path"]).stat().st_size > MAX_LOG_BYTES else None
                result = process.poll()
                if reason is not None or result is not None:
                    if reason is not None or collect_owned(known, process_snapshot()):
                        stop_owned(process, known)
                    result = process.wait(timeout=5)
                    entry.update(status=reason or ("completed" if result == 0 else "failed"), returncode=result)
                    status_path = Path(row["state_directory"]) / "worker-status.json"
                    if status_path.is_file():
                        after_status = status_path.stat()
                        fresh = [after_status.st_ino, after_status.st_mtime_ns] != entry["status_inode_before"]
                        entry["worker_status_observed_this_invocation"] = fresh
                        entry["worker_status" if fresh else "previous_worker_status"] = _read(status_path, 64 * 1024)
                    handle.close(); guard.__exit__(None, None, None)
                    active.remove((process, known, handle, guard, entry, row))
            _write(directory / "wave.json", receipt)
            if active:
                time.sleep(0.1)
    finally:
        cleanup_errors = []
        for process, known, handle, guard, entry, row in active:
            try:
                stop_owned(process, known)
                entry.update(status="launcher_cleanup", returncode=process.returncode)
            except BaseException as exc:
                cleanup_errors.append(type(exc).__name__)
                entry.update(status="cleanup_failed", error_type=type(exc).__name__)
            finally:
                handle.close(); guard.__exit__(None, None, None)
        receipt["finished_at"] = time.time()
        _write(directory / "wave.json", receipt)
        if cleanup_errors:
            raise FleetError("bounded cleanup failed for owned workers: " + ",".join(cleanup_errors))
    return receipt


def run(args, *, planner=plan_wave, wave_runner=run_wave):
    rows = connections(args.connection_file, args.state_directory)
    if args.plan:
        return {"plan_only": True, **planner(args, rows)}
    args.state_directory.mkdir(parents=True, exist_ok=True)
    stop = [False]
    def halt(*unused): stop[0] = True
    previous = {sig: signal.signal(sig, halt) for sig in (signal.SIGTERM, signal.SIGINT)}
    try:
        with exclusive(args.state_directory / "fleet.lock"):
            state_path = args.state_directory / "fleet.json"
            state = _read(state_path) if state_path.exists() else {"schema": SCHEMA, "next_wave": 0, "next_worker": 0}
            if (state.get("schema") != SCHEMA or type(state.get("next_wave")) is not int
                    or type(state.get("next_worker")) is not int
                    or state["next_wave"] < 0 or state["next_worker"] < 0):
                raise FleetError("invalid persisted fleet state")
            if state.get("active_wave_directory"):
                prior = _path(state["active_wave_directory"]) / "wave.json"
                if args.state_directory not in prior.parents:
                    raise FleetError("prior wave is outside this fleet")
                if prior.exists():
                    snapshot = process_snapshot()
                    for worker in _read(prior).get("workers", []):
                        known = {int(pid): birth for pid, birth in worker.get("owned_processes", {}).items()}
                        if collect_owned(known, snapshot):
                            raise FleetError("a prior owned wave is still alive; resume after it exits")
                state.pop("active_wave_directory", None)
            reports, ordinal, failed = [], 0, 0
            while not stop[0] and (args.cycles == 0 or ordinal < args.cycles):
                current_rows = connections(args.connection_file, args.state_directory)
                if current_rows != rows:
                    raise FleetError("fleet connection topology changed")
                plan = planner(args, rows)
                if stop[0]:
                    break
                topology = {"workers": rows, "resource_ledger": str(args.resource_ledger),
                            "campaign_binding_sha256": plan["campaign_binding_sha256"]}
                if "topology" in state and state["topology"] != topology:
                    raise FleetError("persisted fleet topology or campaign binding changed")
                state["topology"] = topology
                count = plan["capacity"]["workers"]
                start = state["next_worker"] % len(rows)
                selected = [rows[(start + offset) % len(rows)] for offset in range(count)]
                wave_number = state["next_wave"]
                directory = args.state_directory / "waves" / (str(wave_number).zfill(8) + "-" + uuid.uuid4().hex)
                directory.parent.mkdir(exist_ok=True)
                state.update(next_wave=wave_number + 1, next_worker=(start + count) % len(rows),
                             active_wave_directory=str(directory))
                _write(state_path, state)
                wave = wave_runner(args, selected, directory, stop) if selected else {"workers": [], "reason": "no_capacity"}
                report = {"wave": wave_number, "plan": plan, "result": wave, "admitted": False}
                _write(args.state_directory / "last-wave.json", report)
                state.pop("active_wave_directory", None)
                _write(state_path, state)
                reports.append({"wave": wave_number, "workers": len(selected),
                                "statuses": [row["status"] for row in wave["workers"]]})
                reports = reports[-32:]
                ordinal += 1
                failed += sum(row["status"] not in {"completed", "identity_busy"} for row in wave["workers"])
                if failed:
                    break
                until = time.monotonic() + args.wave_interval
                while not stop[0] and (args.cycles == 0 or ordinal < args.cycles) and time.monotonic() < until:
                    time.sleep(min(0.1, max(0, until - time.monotonic())))
            return {"schema": SCHEMA, "waves_this_invocation": ordinal, "recent_waves": reports,
                    "interrupted": stop[0], "failed_workers": failed, "admitted": False, "formalized": False}
    finally:
        for sig, handler in previous.items():
            signal.signal(sig, handler)


def parser():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("--state-directory", type=Path, required=True)
    p.add_argument("--connection-file", type=Path, action="append", required=True)
    p.add_argument("--resource-ledger", type=Path, default=DEFAULT_LEDGER)
    p.add_argument("--cycles", type=int, default=1, help="0 explicitly runs continuous bounded waves")
    p.add_argument("--max-workers", type=int, default=0, help="0 sizes automatically, at most the 32 configured identities")
    p.add_argument("--pending-jobs", type=int, help="optional work-count ceiling for each training wave")
    p.add_argument("--memory-budget-mb", type=int, default=2_147_483_647, help="optional total fleet ceiling; hardware and scheduler capacity still apply")
    p.add_argument("--cpu-budget", type=int)
    p.add_argument("--worker-storage-bytes", type=int, default=750_000_000)
    p.add_argument("--training-storage-bytes", type=int, default=750_000_000)
    p.add_argument("--wave-timeout", type=float, default=1200)
    p.add_argument("--wave-interval", type=float, default=30)
    p.add_argument("--lease-seconds", type=float, default=300)
    p.add_argument("--sync-only", action="store_true")
    p.add_argument("--plan", action="store_true", help="read-only capacity and owner-policy observation; no downloads or launch")
    return p


def main(argv=None):
    p = parser(); args = p.parse_args(argv)
    if args.cycles < 0 or args.cycles > 10000 or not 0 <= args.max_workers <= 32 or args.pending_jobs is not None and args.pending_jobs < 0:
        p.error("invalid bounded cycle, worker or pending-job count")
    if args.memory_budget_mb < 0 or args.cpu_budget is not None and args.cpu_budget < 0:
        p.error("resource budgets must be nonnegative")
    if not all(1 <= value <= 50_000_000_000 for value in (args.worker_storage_bytes, args.training_storage_bytes)):
        p.error("each storage allowance must be in (0,50GB]")
    if not math.isfinite(args.wave_timeout) or not 1 <= args.wave_timeout <= 86400 or not math.isfinite(args.wave_interval) or not 0 <= args.wave_interval <= 3600 or not math.isfinite(args.lease_seconds) or not 120 <= args.lease_seconds <= 86400:
        p.error("invalid finite timeout, interval or lease bound")
    args.state_directory, args.resource_ledger = _path(args.state_directory), _path(args.resource_ledger)
    try:
        result = run(args)
    except (FleetError, BlockingIOError) as exc:
        p.error(str(exc) if isinstance(exc, FleetError) else "fleet or worker identity is already active")
    print(json.dumps(result, sort_keys=True, allow_nan=False))
    return 130 if result.get("interrupted") else 1 if result.get("failed_workers") else 0


if __name__ == "__main__":
    raise SystemExit(main())
